/**
 * @module agentFeedbackStore
 * @description Agent 反馈 Store — 反馈收集、评分汇总、状态管理
 * @created 2026-07-04
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import type { AgentFeedback, AgentFeedbackSummary } from '@/types/modules/agent.types'

const logger = getLogger()

interface AgentFeedbackState {
  feedbacks: AgentFeedback[]
  summaries: Map<string, AgentFeedbackSummary>
  isLoading: boolean

  addFeedback: (feedback: AgentFeedback) => void
  resolveFeedback: (id: string) => void
  getSummary: (agentId: string) => AgentFeedbackSummary
  refreshSummaries: () => void
}

export const useAgentFeedbackStore = create<AgentFeedbackState>((set, get) => ({
  feedbacks: [],
  summaries: new Map(),
  isLoading: false,

  addFeedback: (feedback) => {
    set((s) => ({
      feedbacks: [...s.feedbacks, feedback],
    }))
    logger.info('[AgentFeedbackStore] Feedback added', {
      taskId: feedback.taskId,
      rating: feedback.rating,
    })
  },

  resolveFeedback: (id) => {
    set((s) => ({
      feedbacks: s.feedbacks.map((f) => (f.id === id ? { ...f, resolved: true } : f)),
    }))
    logger.info('[AgentFeedbackStore] Feedback resolved', { id })
  },

  getSummary: (agentId) => {
    const feedbacks = get().feedbacks.filter((f) => f.agentId === agentId)
    if (feedbacks.length === 0) {
      return { agentId, averageRating: 0, totalFeedback: 0, categoryBreakdown: {} }
    }
    const avgRating = feedbacks.reduce((sum, f) => sum + f.rating, 0) / feedbacks.length
    const breakdown: Record<string, number> = {}
    for (const f of feedbacks) {
      if (f.category == null) {
        logger.warn('[agentFeedbackStore] 字段缺失，使用默认值', { field: 'category', context: `agentId=${f.agentId}` })
        continue // 跳过无分类的反馈，避免污染 breakdown 数据
      }
      const prev = breakdown[f.category]
      const count = prev ?? 0
      breakdown[f.category] = count + 1
    }
    return {
      agentId,
      averageRating: Math.round(avgRating * 10) / 10,
      totalFeedback: feedbacks.length,
      categoryBreakdown: breakdown,
    }
  },

  refreshSummaries: () => {
    const agents = [...new Set(get().feedbacks.map((f) => f.agentId))]
    const map = new Map<string, AgentFeedbackSummary>()
    for (const agentId of agents) {
      map.set(agentId, get().getSummary(agentId))
    }
    set({ summaries: map })
    logger.info('[AgentFeedbackStore] Summaries refreshed', { count: map.size })
  },
}))

// @module analysisNewsStore
// @lifecycle @Analysis
// 分析舱-智能资讯页面的全局状态管理（Zustand）。
// 从 analysis/NewsPage 组件内 4 个 useState 迁移至独立 Store。
//
// 管理范围：
// - 数据层：articles / loading
// - UI 层：filter / selectedArticle
//
// @migration 从 analysis/NewsPage.tsx 的 4 个 useState 迁移而来
import { create } from 'zustand'
import type { NewsArticle } from '@/data/types'
import type { NewsFilterState } from '@/components/news/NewsFilterPanel'
import { listNews, saveNewsArticles } from '@/services/news/newsService'
import { generateMockArticles } from '@/services/news/newsService'
import {
  aggregateSentimentTrend,
  extractStockOptions,
  extractIndustryOptions,
} from '@/services/news/sentimentTrendEngine'
import type { SentimentTrendDimension, SentimentTrendSeries } from '@/types/modules/news.types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

export interface AnalysisNewsState {
  articles: NewsArticle[]
  loading: boolean
  filter: NewsFilterState
  selectedArticle: NewsArticle | null
  /** 情感趋势数据 */
  sentimentTrend: SentimentTrendSeries | null
  /** 股票选项列表 */
  sentimentStockOptions: string[]
  /** 行业选项列表 */
  sentimentIndustryOptions: string[]

  // Actions
  setArticles: (articles: NewsArticle[]) => void
  setLoading: (loading: boolean) => void
  setFilter: (filter: NewsFilterState) => void
  selectArticle: (article: NewsArticle | null) => void
  reset: () => void
  fetchArticles: () => Promise<void>
  // @compliance [DF-002] generateMockArticles 封装 Service 调用，组件通过 Store action 间接调用
  // 整改背景：原 NewsPage 直接 import Service 函数，现通过 Store action 中转
  // 相关规范：docs/implementation/data-flow-spec.md 第5.1节
  generateMockArticles: () => Promise<void>
  /** 计算情感趋势（封装 sentimentTrendEngine 的聚合与选项提取） */
  computeSentimentTrend: (dimension: SentimentTrendDimension, value?: string) => void
}

const DEFAULT_FILTER: NewsFilterState = {
  keyword: '',
  category: '',
  sentiment: '',
  source: '',
}

const initialState = {
  articles: [] as NewsArticle[],
  loading: false,
  filter: { ...DEFAULT_FILTER },
  selectedArticle: null as NewsArticle | null,
  sentimentTrend: null as SentimentTrendSeries | null,
  sentimentStockOptions: [] as string[],
  sentimentIndustryOptions: [] as string[],
}

export const useAnalysisNewsStore = create<AnalysisNewsState>((set, get) => ({
  ...initialState,

  setArticles: (articles) => set({ articles }),
  setLoading: (loading) => set({ loading }),
  setFilter: (filter) => set({ filter }),
  selectArticle: (article) => set({ selectedArticle: article }),

  reset: () => set(initialState),

  fetchArticles: async () => {
    const { filter } = get()
    set({ loading: true })
    try {
      const result = await listNews({
        keyword: filter.keyword || undefined,
        category: filter.category || undefined,
        sentiment: filter.sentiment || undefined,
        source: filter.source || undefined,
      })
      if (result.success && result.data) {
        set({ articles: result.data })
      }
    } finally {
      set({ loading: false })
    }
  },

  // @compliance [DF-002] generateMockArticles 封装 Service 调用
  // - 防重入锁：通过 loading 状态防止并发调用
  // - 日志追踪：logger.info 打印核心分支
  generateMockArticles: async () => {
    const { loading } = get()
    // @note 防重入锁
    if (loading) {
      logger.info('[analysisNewsStore] generateMockArticles skipped: loading=true')
      return
    }
    set({ loading: true })
    try {
      const mockArticles = generateMockArticles(5)
      const saveResult = await saveNewsArticles(mockArticles)
      if (saveResult.success) {
        logger.info('[analysisNewsStore] generateMockArticles: saved', {
          count: saveResult.data?.length ?? 0,
        })
        // 保存成功后刷新列表
        const { fetchArticles } = get()
        await fetchArticles()
        logger.info('[analysisNewsStore] generateMockArticles: refreshed list')
      } else {
        logger.info('[analysisNewsStore] generateMockArticles: save failed', {
          error: saveResult.error,
        })
      }
    } finally {
      set({ loading: false })
    }
  },

  computeSentimentTrend: (dimension, value) => {
    const { articles } = get()
    logger.info('[analysisNewsStore] computeSentimentTrend', { dimension, value, articleCount: articles.length })

    const stockOptions = extractStockOptions(articles)
    const industryOptions = extractIndustryOptions(articles)
    const trend = aggregateSentimentTrend(articles, {
      dimension,
      value: value || undefined,
      fillGaps: true,
    })

    set({
      sentimentTrend: trend,
      sentimentStockOptions: stockOptions,
      sentimentIndustryOptions: industryOptions,
    })
    logger.info('[analysisNewsStore] computeSentimentTrend 完成', {
      pointCount: trend.data.length,
      stockOptions: stockOptions.length,
      industryOptions: industryOptions.length,
    })
  },
}))

/**
 * @module analysisStore
 * @description 分析舱（AnalysisApp）状态管理层。集中管理分析标的列表、V6 批量评分及加载状态。
 * 从 AnalysisApp 组件中抽取的 3 个 useState，实现 Store 化。
 *
 * @see @/apps/analysis/AnalysisApp.tsx - 消费此 Store 的分析舱 UI
 * @see @/services/analysis/analysisService.ts - 底层数据服务
 * @see @/services/scoring/v6ScoreService.ts - V6 评分计算服务
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import type { Stock, V6Score } from '@/data/types'
import { listStocks, listV6Scores } from '@/services/analysis/analysisService'
import { runV6Score } from '@/services/scoring/v6ScoreService'
import {
  loadIndustryScoreTrend,
  loadStockScoreTrend,
  type ScoreTrendData,
  type ScoreTrendEntityType,
  type ScoreTrendPeriod,
} from '@/services/analysis/scoreTrendService'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'

const logger = getLogger()

// ============================================================
// Store 接口
// ============================================================

interface AnalysisState {
  /** 分析标的列表 */
  stocks: Stock[]
  /** V6 评分列表 */
  scores: V6Score[]
  /** 加载状态（标的加载 / 评分计算共用） */
  loading: boolean
  /** 错误信息 */
  error: string | null

  /** 多周期趋势数据 */
  trendData: ScoreTrendData | undefined
  /** 趋势加载状态 */
  trendLoading: boolean
  /** 趋势错误信息 */
  trendError: string | null
  /** 当前趋势周期 */
  trendPeriod: ScoreTrendPeriod

  // Actions
  /** 加载标的列表并刷新评分 */
  loadStocks: () => Promise<void>
  /** 对指定标的运行 V6 评分，完成后自动刷新评分列表 */
  handleScore: (symbol: string) => Promise<void>
  /** 刷新评分列表（静默） */
  loadScores: () => Promise<void>
  /** 清空错误 */
  clearError: () => void
  /** 切换趋势周期 */
  setTrendPeriod: (period: ScoreTrendPeriod) => void
  /** 加载指定实体（行业/个股）的多周期趋势 */
  loadTrend: (entityId: string, entityType: ScoreTrendEntityType, period?: ScoreTrendPeriod) => Promise<void>
  /** 清空趋势错误 */
  clearTrendError: () => void
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  stocks: [] as Stock[],
  scores: [] as V6Score[],
  loading: false,
  error: null as string | null,
  trendData: undefined as ScoreTrendData | undefined,
  trendLoading: false,
  trendError: null as string | null,
  trendPeriod: 'month' as ScoreTrendPeriod,
}

// ============================================================
// Store
// ============================================================

export const useAnalysisStore = create<AnalysisState>((set, get) => ({
  ...initialState,

  loadStocks: async () => {
    logger.info('[analysisStore] loadStocks 开始')
    set({ loading: true, error: null })

    try {
      const result = await listStocks()
      if (result.success && result.data) {
        set({ stocks: result.data, loading: false })
        logger.info(`[analysisStore] loadStocks 完成: ${result.data.length} 只标的`)
      } else {
        const message = result.error ?? '无法加载标的列表'
        logger.error(`[analysisStore] loadStocks 失败: ${message}`)
        set({ loading: false, error: message })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : '无法加载标的列表'
      logger.error(`[analysisStore] loadStocks 异常: ${message}`)
      set({ loading: false, error: message })
    }
  },

  handleScore: async (symbol: string) => {
    logger.info(`[analysisStore] handleScore 开始: ${symbol}`)
    set({ loading: true, error: null })

    try {
      const result = await runV6Score(symbol)
      if (result.success && result.data) {
        const newScores = get().scores.map((s) =>
          s.symbol === symbol ? result.data! : s,
        )
        if (!newScores.some((s) => s.symbol === symbol)) {
          newScores.push(result.data!)
        }
        set({ scores: newScores, loading: false })
        logger.info(`[analysisStore] handleScore 完成: ${symbol}`)
        // D-3: 广播评分变更事件
        withBroadcast(EVENT_NAMES.SCORES_CHANGED, { action: 'score', symbol })
      } else {
        const message = result.error ?? `无法对 ${symbol} 运行评分`
        logger.error(`[analysisStore] handleScore 失败: ${message}`)
        set({ loading: false, error: message })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : `无法对 ${symbol} 运行评分`
      logger.error(`[analysisStore] handleScore 异常: ${message}`)
      set({ loading: false, error: message })
    }
  },

  loadScores: async () => {
    logger.info('[analysisStore] loadScores 开始')
    try {
      const result = await listV6Scores()
      if (result.success && result.data) {
        set({ scores: result.data })
        logger.info(`[analysisStore] loadScores 完成: ${result.data.length} 条评分`)
        // D-3: 广播评分变更事件
        withBroadcast(EVENT_NAMES.SCORES_CHANGED, { action: 'load', count: result.data.length })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[analysisStore] loadScores 异常: ${message}`)
    }
  },

  clearError: () => {
    set({ error: null })
  },

  setTrendPeriod: (period) => {
    set({ trendPeriod: period })
  },

  loadTrend: async (entityId, entityType, period) => {
    const effectivePeriod = period ?? get().trendPeriod
    logger.info(`[analysisStore] loadTrend 开始: ${entityType}=${entityId}, period=${effectivePeriod}`)
    set({ trendLoading: true, trendError: null, trendPeriod: effectivePeriod })

    try {
      const result = entityType === 'industry'
        ? await loadIndustryScoreTrend(entityId, effectivePeriod)
        : await loadStockScoreTrend(entityId, effectivePeriod)

      if ('data' in result) {
        const data = result.data
        set({ trendData: data, trendLoading: false })
        logger.info(`[analysisStore] loadTrend 完成: ${data.points.length} 个周期点`)
      } else {
        const message = result.error ?? '无法加载趋势数据'
        logger.error(`[analysisStore] loadTrend 失败: ${message}`)
        set({ trendLoading: false, trendError: message })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : '无法加载趋势数据'
      logger.error(`[analysisStore] loadTrend 异常: ${message}`)
      set({ trendLoading: false, trendError: message })
    }
  },

  clearTrendError: () => {
    set({ trendError: null })
  },
}))

/**
 * @module disciplineStore
 * @lifecycle @Global
 * @description 交易纪律与复盘报告 Store。
 * 包装 tradeReviewAI 服务，响应订单变更自动重算纪律评分与复盘报告，
 * 并将复盘摘要持久化到 trade_reviews store。
 *
 * @see docs/《V9核心数据字典与类型定义（整合版）》.md — DisciplineState 实体定义（#69）
 * @see docs/《功能模块数据契约》.md — 交易纪律与复盘模块契约（第 10 节）
 * @see docs/implementation/v9-system-blueprint.md — 5大Store架构（4.3 节）
 * @see src/services/trading/tradeReviewAI.ts — AI 交易复盘服务
 * @see src/services/trading/tradeErrorClassifier.ts — 交易错误分类器
 *
 * @compliance
 * - isRefreshing 锁防止并发重算
 * - 失败时快照回滚，保留旧复盘数据不被清空
 * - 写操作通过 dataBridge.forward() 走信封协议
 * - 订阅 STORE_NAME.orders 频道，source 过滤防自激，100ms 去抖合并
 */

import { create } from 'zustand'
import { subscribeWithSelector } from 'zustand/middleware'
import { getLogger } from '@/lib/logger'
import { dataLayer } from '@/data/dataLayer'
import { dataBridge } from '@/core/databridge'
import { refreshCoordinator } from '@/core/refreshCoordinator'
import {
  ENVELOPE_ACTION,
  MODULE_ID,
  STORE_NAME,
  type EnvelopeAction,
} from '@/config/dbConfig'
import type { Order } from '@/data/types'
import type { StandardEnvelope } from '@/core/envelope'
import { useOrderStore } from './orderStore'
import {
  generateReview,
  generateReviewAsync,
  type TradeError,
  type TradeReviewRecord,
  type TradeReviewReport,
  type PsychologicalProfile,
} from '@/services/trading/tradeReviewAI'
import { classifyErrors } from '@/services/trading/tradeErrorClassifier'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

export interface DisciplineState {
  /** 最新复盘报告 */
  latestReport: TradeReviewReport | null
  /** 交易错误列表（由错误分类器检测出的全部错误实例） */
  tradeErrors: TradeError[]
  /** 纪律评分 */
  disciplineScore: number
  /** 技能发展路径标题列表 */
  skillRoadmap: string[]
  /** 心理画像 */
  psychologicalProfile: PsychologicalProfile | null

  // ---- 加载状态 ----
  /** 是否正在加载（首次加载） */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 是否正在刷新中（用于并发锁） */
  isRefreshing: boolean
  /** 最后更新时间戳 */
  lastUpdated: number

  // ---- Actions ----
  /**
   * 根据订单列表重新计算复盘报告与纪律评分。
   * 未传入 orders 时，先调用 orderStore.refresh() 再读取全部订单。
   */
  recalculate: (orders?: Order[]) => Promise<void>
  /**
   * 从 trade_reviews store 读取已持久化的复盘结果。
   */
  refresh: () => Promise<void>
  /**
   * 重置 store 到初始空状态。
   */
  reset: () => void
  /** 加载全部交易记录（封装 dataLayer.orders.list，避免页面直接调用 dataLayer） */
  loadOrders: () => Promise<Order[]>
  /** 同步生成交易复盘报告（封装 generateReview，避免页面直接调用 Service） */
  generateReviewReport: (orders: Order[]) => TradeReviewReport
}

// ============================================================
// 初始状态
// ============================================================

const initialState: Omit<
  DisciplineState,
  'recalculate' | 'refresh' | 'reset' | 'loadOrders' | 'generateReviewReport'
> = {
  latestReport: null,
  tradeErrors: [],
  disciplineScore: 100,
  skillRoadmap: [],
  psychologicalProfile: null,
  loading: true,
  error: null,
  isRefreshing: false,
  lastUpdated: 0,
}

// ============================================================
// 工具函数
// ============================================================

/**
 * 从复盘报告中提取需要独立维护的派生字段。
 */
function extractReviewDerived(report: TradeReviewReport) {
  return {
    disciplineScore: report.summary.disciplineScore,
    skillRoadmap: report.skillDevelopment.learningPath.map((node) => node.title),
    psychologicalProfile: report.errorAnalysis.psychologicalProfile,
  }
}

// ============================================================
// Store
// ============================================================

export const useDisciplineStore = create<DisciplineState>()(
  subscribeWithSelector((set, get) => ({
    ...initialState,

    // ----------------------------------------------------------
    // recalculate —— 重新计算复盘报告
    // ----------------------------------------------------------

    /**
     * 重新计算交易复盘报告。
     *
     * @remarks
     * - 具备 isRefreshing 并发锁，防止重复调用
     * - 未传入 orders 时，先触发 orderStore.refresh() 获取最新订单
     * - 调用 tradeReviewAI.generateReviewAsync(orders) 生成报告
     * - 提取关键派生字段并持久化报告摘要到 trade_reviews store
     * - 失败时回滚到旧快照，仅更新 error / loading 状态
     */
    recalculate: async (orders?: Order[]) => {
      const state = get()

      // 并发锁：已在重算中则跳过
      if (state.isRefreshing) {
        logger.debug('[disciplineStore] recalculate skipped: isRefreshing is true')
        return
      }

      // 保存旧数据快照，用于失败回滚
      const snapshot = {
        latestReport: state.latestReport,
        tradeErrors: state.tradeErrors,
        disciplineScore: state.disciplineScore,
        skillRoadmap: state.skillRoadmap,
        psychologicalProfile: state.psychologicalProfile,
        lastUpdated: state.lastUpdated,
      }

      set({
        isRefreshing: true,
        loading: state.latestReport === null,
        error: null,
      })

      try {
        logger.info('[disciplineStore] recalculate 开始')

        let targetOrders = orders
        if (!targetOrders) {
          // 通过 RefreshCoordinator 等待 orderStore 刷新完成，
          // 避免 orderStore 正在刷新时 disciplineStore 读到过期数据
          await refreshCoordinator.waitFor('orderStore')
          await useOrderStore.getState().refresh()
          targetOrders = useOrderStore.getState().orders
        }

        logger.info(`[disciplineStore] 生成复盘报告: 订单数=${targetOrders.length}`)
        const report = await generateReviewAsync(targetOrders)
        const derived = extractReviewDerived(report)

        // 同步执行错误分类，获取完整 DetectedError 列表用于独立状态与持久化
        const classification = classifyErrors(targetOrders)

        // 持久化复盘摘要
        const record: TradeReviewRecord = {
          id: 'latest',
          generatedAt: report.generatedAt,
          report,
          tradeErrors: classification.errors,
          ...derived,
        }

        const saveResult = await dataLayer.tradeReviews.save(record)
        if (!saveResult.success) {
          logger.warn('[disciplineStore] 复盘摘要持久化失败', { error: saveResult.error })
        } else {
          logger.info('[disciplineStore] 复盘摘要已持久化')
        }

        set({
          latestReport: report,
          tradeErrors: classification.errors,
          ...derived,
          loading: false,
          error: null,
          isRefreshing: false,
          lastUpdated: Date.now(),
        })

        logger.info('[disciplineStore] recalculate 完成', {
          disciplineScore: derived.disciplineScore,
          totalTrades: report.summary.totalTrades,
        })
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        logger.error('[disciplineStore] recalculate 失败，回滚到旧快照', { error: message })

        set({
          ...snapshot,
          loading: false,
          error: message,
          isRefreshing: false,
        })
      }
    },

    // ----------------------------------------------------------
    // refresh —— 从持久化存储恢复复盘结果
    // ----------------------------------------------------------

    /**
     * 从 trade_reviews store 读取最新复盘记录并恢复状态。
     *
     * @remarks
     * - 具备 isRefreshing 并发锁
     * - 失败时保留旧数据快照，仅更新 error / loading 状态
     */
    refresh: async () => {
      const state = get()

      // 并发锁
      if (state.isRefreshing) {
        logger.debug('[disciplineStore] refresh skipped: isRefreshing is true')
        return
      }

      const snapshot = {
        latestReport: state.latestReport,
        tradeErrors: state.tradeErrors,
        disciplineScore: state.disciplineScore,
        skillRoadmap: state.skillRoadmap,
        psychologicalProfile: state.psychologicalProfile,
        lastUpdated: state.lastUpdated,
      }

      set({
        isRefreshing: true,
        loading: state.latestReport === null,
        error: null,
      })

      try {
        logger.info('[disciplineStore] refresh 开始')
        const record = await dataLayer.tradeReviews.getLatest() as TradeReviewRecord | null

        if (!record) {
          logger.info('[disciplineStore] 未找到已持久化的复盘记录')
          set({
            loading: false,
            error: null,
            isRefreshing: false,
          })
          return
        }

        set({
          latestReport: record.report,
          tradeErrors: record.tradeErrors,
          disciplineScore: record.disciplineScore,
          skillRoadmap: record.skillRoadmap,
          psychologicalProfile: record.psychologicalProfile,
          loading: false,
          error: null,
          isRefreshing: false,
          lastUpdated: record.generatedAt,
        })

        logger.info('[disciplineStore] refresh 完成', {
          disciplineScore: record.disciplineScore,
          generatedAt: record.generatedAt,
        })
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        logger.error('[disciplineStore] refresh 失败，回滚到旧快照', { error: message })

        set({
          ...snapshot,
          loading: false,
          error: message,
          isRefreshing: false,
        })
      }
    },

    // ----------------------------------------------------------
    // reset —— 重置
    // ----------------------------------------------------------

    reset: () => {
      logger.info('[disciplineStore] reset')
      set({ ...initialState })
      withBroadcast(EVENT_NAMES.DISCIPLINE_CHANGED, { action: 'reset' })
    },

    loadOrders: async () => {
      logger.info('[disciplineStore] loadOrders 开始')
      try {
        const orders = await dataLayer.orders.list()
        logger.info(`[disciplineStore] loadOrders 完成: ${orders.length} 笔`)
        return orders
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        logger.error(`[disciplineStore] loadOrders 异常: ${message}`)
        throw err
      }
    },

    generateReviewReport: (orders) => {
      logger.info(`[disciplineStore] generateReviewReport 开始: ${orders.length} 笔`)
      try {
        const report = generateReview(orders)
        logger.info('[disciplineStore] generateReviewReport 完成')
        return report
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        logger.error(`[disciplineStore] generateReviewReport 异常: ${message}`)
        throw err
      }
    },
  })),
)

// ============================================================
// DataBridge 订阅生命周期
// ============================================================

/** 本模块 source 标识，用于订阅时 source 过滤，防止自激 */
const DISCIPLINE_STORE_SOURCE = MODULE_ID.trading

/** 去抖合并窗口（毫秒）：短时间内多次变更合并为一次 recalculate */
const DEBOUNCE_MS = 100

let _unsubscribeOrders: (() => void) | null = null
let _debounceTimer: ReturnType<typeof setTimeout> | null = null

/** 需要触发重算的订单相关 action 集合 */
const _ORDER_CHANGE_ACTIONS = new Set<EnvelopeAction>([
  ENVELOPE_ACTION.insertOrder,
  ENVELOPE_ACTION.updateOrder,
  ENVELOPE_ACTION.deleteOrder,
  ENVELOPE_ACTION.tradeActionExecuted,
])

/**
 * 去抖执行 recalculate，100ms 内多次调用合并为一次。
 */
function _debouncedRecalculate(envelope: StandardEnvelope): void {
  if (_debounceTimer) {
    clearTimeout(_debounceTimer)
  }
  _debounceTimer = setTimeout(() => {
    _debounceTimer = null
    logger.info('[disciplineStore] Debounced recalculate triggered', {
      traceId: envelope.meta.traceId,
      action: envelope.meta.action,
      source: envelope.meta.source,
    })
    useDisciplineStore.getState().recalculate()
  }, DEBOUNCE_MS)
}

/**
 * 初始化 DisciplineStore 的 DataBridge 订阅。
 *
 * 订阅 STORE_NAME.orders 频道，监听以下 action 并触发去抖动重算：
 * - insertOrder
 * - updateOrder
 * - deleteOrder
 * - tradeActionExecuted
 *
 * 同时做 source 过滤：跳过 source 为 'trading' 的事件，防止自激。
 *
 * @returns 清理函数，调用后取消所有订阅并清理定时器
 */
export function initDisciplineStoreSubscriptions(): () => void {
  if (_unsubscribeOrders) {
    logger.warn('[disciplineStore] Subscriptions already initialized, skipping')
    return _unsubscribeOrders
  }

  _unsubscribeOrders = dataBridge.subscribe(
    STORE_NAME.orders,
    (envelope) => {
      // source 过滤：跳过本模块发出的事件，防止自激
      if (envelope.meta.source === DISCIPLINE_STORE_SOURCE) {
        return
      }

      if (_ORDER_CHANGE_ACTIONS.has(envelope.meta.action)) {
        logger.info('[disciplineStore] DataBridge orders event, scheduling debounced recalculate', {
          action: envelope.meta.action,
          traceId: envelope.meta.traceId,
          source: envelope.meta.source,
        })
        _debouncedRecalculate(envelope)
      }
    },
  )

  logger.info('[disciplineStore] DataBridge orders subscriptions initialized')

  /** 清理函数：取消订阅 + 清除去抖定时器 */
  return () => {
    if (_debounceTimer) {
      clearTimeout(_debounceTimer)
      _debounceTimer = null
    }
    _unsubscribeOrders?.()
    _unsubscribeOrders = null
    logger.info('[disciplineStore] DataBridge subscriptions destroyed')
  }
}

/**
 * @module dualStrategyStore
 * @lifecycle @Global
 * @description 双策略信号池（Dual Strategy Signal Pool）。
 * 合并 hotSectorStore、valuePitStore、rotationSignalStore 的职责，成为统一的
 * 热门板块评分、价值洼地评分、轮动信号状态管理中心。
 *
 * 数据来源与持久化：
 * - 计算层统一调用 dualStrategyEngine.runDualStrategy() 一次性产出三类结果。
 * - 持久化到 DataBridge：hot_sector_scores / value_pit_scores / signals（轮动信号）。
 * - 刷新时从 dataLayer 读取已持久化的评分与信号。
 *
 * @see docs/《V9核心数据字典与类型定义（整合版）》.md — DualStrategyState 实体定义（#68）
 * @see docs/《功能模块数据契约》.md — 双策略信号池模块契约（第 9 节）
 * @see docs/implementation/v9-system-blueprint.md — 5大Store架构（4.3 节）
 * @see src/services/trading/dualStrategyEngine.ts — 双策略计算引擎
 * @see src/services/scoring/hotSectorAnalyzer.ts — 热门板块评分分析器
 * @see src/services/scoring/valuePitAnalyzer.ts — 价值洼地评分分析器
 * @see src/services/scoring/rotationSignalDetector.ts — 轮动信号检测器
 *
 * @compliance
 * - 所有展示数据来自 scoring / trading 服务，禁止硬编码
 * - 使用 isRefreshing 锁与失败快照回滚
 * - 订阅采用去抖合并，source 过滤防止自激
 * - 遵循现有 Zustand Store 风格
 */

