  const { valuePitScores } = useDualStrategyStore.getState()
  return valuePitScores.find((s) => s.symbol === symbol)
}

/** 按 sectorId 查询轮动信号 */
export function rotationSignalBySector(sectorId: string): RotationSignal | undefined {
  const { rotationSignals } = useDualStrategyStore.getState()
  return rotationSignals.find((s) => s.sectorId === sectorId)
}

// ============================================================
// DataBridge 订阅生命周期
// ============================================================
// 订阅以下频道变更，去抖刷新：
// - hot_sector_scores
// - value_pit_scores
// - rotation_scores（板块轮动评分，外部模块写入时触发同步）
// - signals（轮动信号实际持久化位置）
// - stocks（股票池变更会驱动评分重新计算）
//
// source 过滤：跳过 analyzer / tradinghub / strategy 模块自身发出的事件，
// 避免自激循环。
// ============================================================

let _unsubscribeHot: (() => void) | null = null
let _unsubscribeValue: (() => void) | null = null
let _unsubscribeRotation: (() => void) | null = null
let _unsubscribeSignals: (() => void) | null = null
let _unsubscribeStocks: (() => void) | null = null
let _debounceTimer: ReturnType<typeof setTimeout> | null = null
const DEBOUNCE_MS = 100

const SELF_SOURCES = new Set<string>([
  MODULE_ID.analyzer,
  MODULE_ID.tradinghub,
  MODULE_ID.strategy,
])

function debouncedRefresh(): void {
  if (_debounceTimer) {
    clearTimeout(_debounceTimer)
  }
  _debounceTimer = setTimeout(() => {
    _debounceTimer = null
    const state = useDualStrategyStore.getState()
    if (state.isRefreshing) {
      logger.debug('[dualStrategyStore] refresh 进行中，跳过本次触发')
      return
    }
    logger.info('[dualStrategyStore] DataBridge 事件触发自动 refresh')
    void state.refresh()
  }, DEBOUNCE_MS)
}

export function shouldSkipSelf(envelope: { meta: { source: string; action: string } }): boolean {
  if (SELF_SOURCES.has(envelope.meta.source)) {
    return true
  }
  // 策略刷新 action 也由外部触发，但源可能是 strategy，已包含在上面的集合中
  return false
}

/** 初始化 DataBridge 订阅，返回 cleanup 函数 */
export function initDualStrategyStoreSubscriptions(): () => void {
  if (_unsubscribeHot || _unsubscribeValue || _unsubscribeRotation || _unsubscribeSignals || _unsubscribeStocks) {
    logger.warn('[dualStrategyStore] Subscriptions already initialized, skipping')
    return () => destroyDualStrategyStoreSubscriptions()
  }

  logger.info('[dualStrategyStore] 初始化 DataBridge 订阅')

  _unsubscribeHot = dataBridge.subscribe(
    STORE_NAME.hotSectorScores,
    (envelope) => {
      if (shouldSkipSelf(envelope)) return
      logger.info('[dualStrategyStore] hotSectorScores 频道收到变更', {
        action: envelope.meta.action,
        source: envelope.meta.source,
        traceId: envelope.meta.traceId,
      })
      debouncedRefresh()
    },
  )

  _unsubscribeValue = dataBridge.subscribe(
    STORE_NAME.valuePitScores,
    (envelope) => {
      if (shouldSkipSelf(envelope)) return
      logger.info('[dualStrategyStore] valuePitScores 频道收到变更', {
        action: envelope.meta.action,
        source: envelope.meta.source,
        traceId: envelope.meta.traceId,
      })
      debouncedRefresh()
    },
  )

  _unsubscribeRotation = dataBridge.subscribe(
    STORE_NAME.rotationScores,
    (envelope) => {
      if (shouldSkipSelf(envelope)) return
      logger.info('[dualStrategyStore] rotationScores 频道收到变更', {
        action: envelope.meta.action,
        source: envelope.meta.source,
        traceId: envelope.meta.traceId,
      })
      debouncedRefresh()
    },
  )

  _unsubscribeSignals = dataBridge.subscribe(
    STORE_NAME.signals,
    (envelope) => {
      if (shouldSkipSelf(envelope)) return
      logger.info('[dualStrategyStore] signals 频道收到变更', {
        action: envelope.meta.action,
        source: envelope.meta.source,
        traceId: envelope.meta.traceId,
      })
      debouncedRefresh()
    },
  )

  _unsubscribeStocks = dataBridge.subscribe(
    STORE_NAME.stocks,
    (envelope) => {
      if (envelope.meta.source === MODULE_ID.stockpool) return
      logger.info('[dualStrategyStore] stocks 频道收到变更', {
        action: envelope.meta.action,
        source: envelope.meta.source,
        traceId: envelope.meta.traceId,
      })
      debouncedRefresh()
    },
  )

  return () => destroyDualStrategyStoreSubscriptions()
}

function destroyDualStrategyStoreSubscriptions(): void {
  if (_debounceTimer) {
    clearTimeout(_debounceTimer)
    _debounceTimer = null
  }
  _unsubscribeHot?.()
  _unsubscribeValue?.()
  _unsubscribeRotation?.()
  _unsubscribeSignals?.()
  _unsubscribeStocks?.()
  _unsubscribeHot = null
  _unsubscribeValue = null
  _unsubscribeRotation = null
  _unsubscribeSignals = null
  _unsubscribeStocks = null
  logger.info('[dualStrategyStore] DataBridge subscriptions destroyed')
}

/**
 * @module executionStore
 * @lifecycle @Global
 * @description 执行中枢 -- 信号到订单之间的执行状态机。
 * 封装执行计划生成、状态转换(plan->confirmed->pending->executed->cancelled->reviewed)、
 * 自动执行编排、执行日志。
 *
 * @compliance
 * - isRefreshing 锁防止并发刷新
 * - 失败时快照回滚，保留旧数据不被清空
 * - 所有写操作通过 dataBridge.forward() 走信封协议
 * - 订阅 STORE_NAME.signals / STORE_NAME.orders 频道，source 过滤防自激
 *
 * @see docs/《V9核心数据字典与类型定义（整合版）》.md
 * @see docs/《功能模块数据契约》.md
 * @see docs/implementation/v9-system-blueprint.md
 * @see docs/《DataBridge端点与数据映射清单》.md
 * @see docs/《V9 架构缺陷与整改行动清单》.md
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { dataLayer } from '@/data/dataLayer'
import { refreshCoordinator } from '@/core/refreshCoordinator'
import {
  ENVELOPE_ACTION,
  MODULE_ID,
  STORE_NAME,
  type AccountType,
  type EnvelopeAction,
} from '@/config/dbConfig'
import type { Signal, ExecutionPlan, ExecutionPhase } from '@/data/types'
import type { StandardEnvelope } from '@/core/envelope'
import { dataBridge } from '@/core/databridge'
import { createBuyOrder, createSellOrder } from '@/services/trading/tradingService'
import { createExecutionPlanUseCase } from '@/services/useCase/createExecutionPlan.useCase'

const logger = getLogger()

/** 执行计划手动取消时的默认错误信息 */
const DEFAULT_CANCEL_REASON = '手动取消'

// ============================================================
// 类型定义
// ============================================================

interface ExecutionState {
  // ---- 核心数据 ----
  /** 全部执行计划 */
  plans: ExecutionPlan[]
  /** 活跃计划：phase in [plan, confirmed, pending] */
  activePlans: ExecutionPlan[]

  // ---- 加载状态 ----
  /** 是否正在处理（执行中） */
  isProcessing: boolean
  /** 是否正在加载（首次加载） */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 是否正在刷新（并发锁） */
  isRefreshing: boolean
  /** 最后更新时间戳 */
  lastUpdated: number

  // ---- Actions ----
  /** 根据信号创建执行计划（计算仓位 + 风控检查） */
  createPlan: (signal: Signal, accountType?: AccountType) => Promise<ExecutionPlan | null>
  /** 确认执行计划：phase plan -> confirmed */
  confirmPlan: (planId: string) => Promise<void>
  /** 执行计划：调用 tradingService 下单 */
  executePlan: (planId: string) => Promise<void>
  /** 取消执行计划 */
  cancelPlan: (planId: string, reason?: string) => Promise<void>
  /** 标记已复盘 */
  markReviewed: (planId: string) => Promise<void>
  /** 从 dataLayer 全量刷新 */
  refresh: () => Promise<void>
}

// ============================================================
// 初始状态
// ============================================================

const initialState: Omit<
  ExecutionState,
  'createPlan' | 'confirmPlan' | 'executePlan' | 'cancelPlan' | 'markReviewed' | 'refresh'
> = {
  plans: [],
  activePlans: [],
  isProcessing: false,
  loading: true,
  error: null,
  isRefreshing: false,
  lastUpdated: 0,
}

// ============================================================
// 工具函数
// ============================================================

/** 判断是否为活跃 phase */
function isActivePhase(phase: ExecutionPhase): boolean {
  return phase === 'plan' || phase === 'confirmed' || phase === 'pending'
}

/** 计算活跃计划列表 */
function computeActivePlans(plans: ExecutionPlan[]): ExecutionPlan[] {
  return plans.filter((p) => isActivePhase(p.phase))
}

// ============================================================
// Store
// ============================================================

export const useExecutionStore = create<ExecutionState>((set, get) => ({
  ...initialState,

  // ----------------------------------------------------------
  // refresh -- 全量刷新
  // ----------------------------------------------------------

  refresh: async () => {
    const state = get()

    // 并发锁
    if (state.isRefreshing) {
      logger.debug('[executionStore] refresh skipped: isRefreshing is true')
      return
    }

    // 保存旧快照，用于失败回滚
    const snapshot = {
      plans: state.plans,
      activePlans: state.activePlans,
      lastUpdated: state.lastUpdated,
    }

    set({ isRefreshing: true, loading: state.plans.length === 0, error: null })

    try {
      logger.info('[executionStore] refresh 开始')
      const plans = await dataLayer.executionPlans.list()
      const activePlans = computeActivePlans(plans)

      set({
        plans,
        activePlans,
        loading: false,
        error: null,
        isRefreshing: false,
        lastUpdated: Date.now(),
      })

      logger.info(`[executionStore] refresh 完成: ${plans.length} 个计划, ${activePlans.length} 个活跃`)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[executionStore] refresh 失败，回滚到旧快照', { error: message })

      set({
        ...snapshot,
        loading: false,
        error: message,
        isRefreshing: false,
      })
    }
  },

  // ----------------------------------------------------------
  // createPlan -- 创建执行计划
  // ----------------------------------------------------------

  createPlan: async (signal, accountType) => {
    logger.info('[executionStore] createPlan', {
      signalId: signal.id,
      symbol: signal.symbol,
      direction: signal.direction,
    })

    try {
      const result = await createExecutionPlanUseCase({ signal, accountType })

      if (!result.success || !result.plan) {
        if (result.error && result.error !== '非交易信号，不创建执行计划') {
          logger.error('[executionStore] createPlan 失败', { error: result.error })
          set({ error: result.error })
        }
        return null
      }

      // 更新 store 状态
      set((state) => {
        const newPlans = [...state.plans, result.plan!]
        return {
          plans: newPlans,
          activePlans: computeActivePlans(newPlans),
          lastUpdated: Date.now(),
        }
      })

      logger.info('[executionStore] createPlan 成功', {
        planId: result.plan.id,
        symbol: result.plan.symbol,
        passed: result.plan.risk?.passed,
      })

      return result.plan
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[executionStore] createPlan 失败', { error: message, symbol: signal.symbol })
      set({ error: message })
      return null
    }
  },

  // ----------------------------------------------------------
  // confirmPlan -- 确认执行计划
  // ----------------------------------------------------------

  confirmPlan: async (planId) => {
    logger.info('[executionStore] confirmPlan', { planId })

    try {
      const { plans } = get()
      const plan = plans.find((p) => p.id === planId)
      if (!plan) {
        logger.error('[executionStore] confirmPlan failed: plan not found', { planId })
        set({ error: `执行计划 ${planId} 不存在` })
        return
      }

      if (plan.phase !== 'plan') {
        logger.error('[executionStore] confirmPlan failed: invalid phase', { planId, phase: plan.phase })
        set({ error: `执行计划 ${planId} 当前阶段为 ${plan.phase}，无法确认` })
        return
      }

      const updated: ExecutionPlan = {
        ...plan,
        phase: 'confirmed',
        confirmedAt: Date.now(),
      }

      await dataLayer.executionPlans.update(planId, { phase: 'confirmed', confirmedAt: Date.now() })

      set((state) => {
        const newPlans = state.plans.map((p) => (p.id === planId ? updated : p))
        return {
          plans: newPlans,
          activePlans: computeActivePlans(newPlans),
          lastUpdated: Date.now(),
        }
      })

      logger.info('[executionStore] confirmPlan 成功', { planId })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[executionStore] confirmPlan 失败', { error: message, planId })
      set({ error: message })
    }
  },

  // ----------------------------------------------------------
  // executePlan -- 执行计划（下单）
  // ----------------------------------------------------------

  executePlan: async (planId) => {
    logger.info('[executionStore] executePlan', { planId })

    const { plans } = get()
    const plan = plans.find((p) => p.id === planId)
    if (!plan) {
      logger.error('[executionStore] executePlan failed: plan not found', { planId })
      set({ error: `执行计划 ${planId} 不存在` })
      return
    }

    if (plan.phase !== 'confirmed' && plan.phase !== 'plan') {
      logger.error('[executionStore] executePlan failed: invalid phase', { planId, phase: plan.phase })
      set({ error: `执行计划 ${planId} 当前阶段为 ${plan.phase}，无法执行` })
      return
    }

    // 设置处理中状态
    set({ isProcessing: true, error: null })

    try {
      // 等待 orderStore 刷新完成，确保读取到最新持仓数据用于仓位计算
      await refreshCoordinator.waitFor('orderStore')

      // 1. phase -> pending
      const pendingPlan: ExecutionPlan = { ...plan, phase: 'pending' }
      await dataLayer.executionPlans.update(planId, { phase: 'pending' })

      set((state) => {
        const newPlans = state.plans.map((p) => (p.id === planId ? pendingPlan : p))
        return { plans: newPlans, activePlans: computeActivePlans(newPlans) }
      })

      // 2. 获取股票信息
      const stock = await dataLayer.stocks.get(plan.symbol)
      if (!stock || stock.price === undefined || stock.price <= 0) {
        throw new Error(`股票 ${plan.symbol} 价格无效`)
      }

      // 3. 根据 direction 调用 tradingService
      const quantity = plan.sizing?.quantity ?? 100
      let orderResult

      if (plan.direction === 'buy') {
        orderResult = await createBuyOrder(stock, quantity)
      } else {
        orderResult = await createSellOrder(stock, quantity)
      }

      // 4. 处理结果
      if (orderResult.success && orderResult.data) {
        const executedPlan: ExecutionPlan = {
          ...pendingPlan,
          phase: 'executed',
          orderId: orderResult.data.id,
          executedAt: Date.now(),
          result: 'success',
        }
        await dataLayer.executionPlans.update(planId, {
          phase: 'executed',
          orderId: orderResult.data.id,
          executedAt: Date.now(),
          result: 'success',
        })

        set((state) => {
          const newPlans = state.plans.map((p) => (p.id === planId ? executedPlan : p))
          return {
            plans: newPlans,
            activePlans: computeActivePlans(newPlans),
            lastUpdated: Date.now(),
          }
        })

        logger.info('[executionStore] executePlan 成功', {
          planId,
          orderId: orderResult.data.id,
        })
      } else {
        // 下单失败 -> cancelled
        const cancelledPlan: ExecutionPlan = {
          ...pendingPlan,
          phase: 'cancelled',
          executedAt: Date.now(),
          result: 'failed',
          errorMessage: orderResult.error ?? '下单失败',
        }
        await dataLayer.executionPlans.update(planId, {
          phase: 'cancelled',
          executedAt: Date.now(),
          result: 'failed',
          errorMessage: orderResult.error ?? '下单失败',
        })

        set((state) => {
          const newPlans = state.plans.map((p) => (p.id === planId ? cancelledPlan : p))
          return {
            plans: newPlans,
            activePlans: computeActivePlans(newPlans),
            lastUpdated: Date.now(),
          }
        })

        logger.warn('[executionStore] executePlan 下单失败', {
          planId,
          error: orderResult.error,
        })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[executionStore] executePlan 异常', { error: message, planId })

      // 异常 -> cancelled
      try {
        const cancelledPlan: ExecutionPlan = {
          ...plan,
          phase: 'cancelled',
          executedAt: Date.now(),
          result: 'failed',
          errorMessage: message,
        }
        await dataLayer.executionPlans.update(planId, {
          phase: 'cancelled',
          executedAt: Date.now(),
          result: 'failed',
          errorMessage: message,
        })

        set((state) => {
          const newPlans = state.plans.map((p) => (p.id === planId ? cancelledPlan : p))
          return {
            plans: newPlans,
            activePlans: computeActivePlans(newPlans),
            lastUpdated: Date.now(),
          }
        })
      } catch (updateErr) {
        logger.error('[executionStore] executePlan 异常后更新状态也失败', { error: updateErr })
      }

      set({ error: message })
    } finally {
      set({ isProcessing: false })
    }
  },

  // ----------------------------------------------------------
  // cancelPlan -- 取消执行计划
  // ----------------------------------------------------------

  cancelPlan: async (planId, reason) => {
    logger.info('[executionStore] cancelPlan', { planId, reason })

    try {
      const { plans } = get()
      const plan = plans.find((p) => p.id === planId)
      if (!plan) {
        logger.error('[executionStore] cancelPlan failed: plan not found', { planId })
        set({ error: `执行计划 ${planId} 不存在` })
        return
      }

      if (plan.phase === 'executed' || plan.phase === 'reviewed' || plan.phase === 'cancelled') {
        logger.warn('[executionStore] cancelPlan skipped: terminal phase', { planId, phase: plan.phase })
        return
      }

      const updated: ExecutionPlan = {
        ...plan,
        phase: 'cancelled',
        errorMessage: reason ?? DEFAULT_CANCEL_REASON,
      }

      await dataLayer.executionPlans.update(planId, {
        phase: 'cancelled',
        errorMessage: reason ?? DEFAULT_CANCEL_REASON,
      })

      set((state) => {
        const newPlans = state.plans.map((p) => (p.id === planId ? updated : p))
        return {
          plans: newPlans,
          activePlans: computeActivePlans(newPlans),
          lastUpdated: Date.now(),
        }
      })

      logger.info('[executionStore] cancelPlan 成功', { planId })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[executionStore] cancelPlan 失败', { error: message, planId })
      set({ error: message })
    }
  },

  // ----------------------------------------------------------
  // markReviewed -- 标记已复盘
  // ----------------------------------------------------------

  markReviewed: async (planId) => {
    logger.info('[executionStore] markReviewed', { planId })

    try {
      const { plans } = get()
      const plan = plans.find((p) => p.id === planId)
      if (!plan) {
        logger.error('[executionStore] markReviewed failed: plan not found', { planId })
        set({ error: `执行计划 ${planId} 不存在` })
        return
      }

      if (plan.phase !== 'executed' && plan.phase !== 'cancelled') {
        logger.warn('[executionStore] markReviewed skipped: not executed/cancelled', { planId, phase: plan.phase })
        return
      }

      const updated: ExecutionPlan = {
        ...plan,
        phase: 'reviewed',
        reviewedAt: Date.now(),
      }

      await dataLayer.executionPlans.update(planId, {
        phase: 'reviewed',
        reviewedAt: Date.now(),
      })

      set((state) => {
        const newPlans = state.plans.map((p) => (p.id === planId ? updated : p))
        return {
          plans: newPlans,
          activePlans: computeActivePlans(newPlans),
          lastUpdated: Date.now(),
        }
      })

      logger.info('[executionStore] markReviewed 成功', { planId })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[executionStore] markReviewed 失败', { error: message, planId })
      set({ error: message })
    }
  },
}))

// ============================================================
// DataBridge 订阅生命周期
// ============================================================

/**
 * 本模块 source 标识，用于订阅时 source 过滤，防止自激。
 */
const EXECUTION_STORE_SOURCE = MODULE_ID.tradinghub

/** 去抖合并窗口（毫秒） */
const DEBOUNCE_MS = 100

let _unsubscribeSignals: (() => void) | null = null
let _unsubscribeOrders: (() => void) | null = null
let _debounceTimer: ReturnType<typeof setTimeout> | null = null

/** 需要触发刷新的执行计划相关 action 集合 */
const _EXECUTION_CHANGE_ACTIONS = new Set<EnvelopeAction>([
  ENVELOPE_ACTION.saveExecutionPlan,
  ENVELOPE_ACTION.updateExecutionPhase,
])

/** 触发自动创建计划的 action 集合 */
const _SIGNAL_INSERT_ACTIONS = new Set<EnvelopeAction>([
  ENVELOPE_ACTION.insertSignal,
])

/** 触发执行计划关联更新的 action 集合 */
const _ORDER_CHANGE_ACTIONS = new Set<EnvelopeAction>([
  ENVELOPE_ACTION.insertOrder,
  ENVELOPE_ACTION.updateOrder,
])

/**
 * 去抖执行 refresh，100ms 内多次调用合并为一次。
 */
function _debouncedRefresh(envelope: StandardEnvelope): void {
  if (_debounceTimer) {
    clearTimeout(_debounceTimer)
  }
  _debounceTimer = setTimeout(() => {
    _debounceTimer = null
    logger.info('[executionStore] Debounced refresh triggered', {
      traceId: envelope.meta.traceId,
      action: envelope.meta.action,
      source: envelope.meta.source,
    })
    useExecutionStore.getState().refresh()
  }, DEBOUNCE_MS)
}

/**
 * 初始化 ExecutionStore 的 DataBridge 订阅。
 *
 * 1. 订阅 STORE_NAME.signals 频道：收到 insertSignal 时，自动调用 createPlan()（半自动模式）
 * 2. 订阅 STORE_NAME.orders 频道：订单状态变更时，更新关联执行计划的 phase
 * 3. source 过滤防止自激
 *
 * @returns 清理函数，调用后取消所有订阅并清理定时器
 *
 * @example
 * ```ts
 * useEffect(() => {
 *   const cleanup = initExecutionStoreSubscriptions()
 *   return cleanup
 * }, [])
 * ```
 */
export function initExecutionStoreSubscriptions(): () => void {
  if (_unsubscribeSignals || _unsubscribeOrders) {
    logger.warn('[executionStore] Subscriptions already initialized, skipping')
    return _destroySubscriptions
  }

  // 订阅 signals 频道：半自动模式下，收到新信号自动创建执行计划
  _unsubscribeSignals = dataBridge.subscribe(
    STORE_NAME.signals,
    (envelope) => {
      // source 过滤：跳过本模块发出的事件，防止自激
      if (envelope.meta.source === EXECUTION_STORE_SOURCE) {
        return
      }

      if (_SIGNAL_INSERT_ACTIONS.has(envelope.meta.action)) {
        const signal = envelope.payload as Signal | undefined
        if (signal && (signal.direction === 'buy' || signal.direction === 'sell')) {
          logger.info('[executionStore] 收到新信号，自动创建执行计划', {
            signalId: signal.id,
            symbol: signal.symbol,
            direction: signal.direction,
            confidence: signal.confidence,
          })
          // 半自动模式：自动创建计划，但不自动确认和执行
          void useExecutionStore.getState().createPlan(signal)
        }
      }

      // 同步刷新执行计划列表
      if (_EXECUTION_CHANGE_ACTIONS.has(envelope.meta.action)) {
        _debouncedRefresh(envelope)
      }
    },
  )

  // 订阅 orders 频道：订单状态变更时更新关联执行计划
  _unsubscribeOrders = dataBridge.subscribe(
    STORE_NAME.orders,
    (envelope) => {
      // source 过滤：跳过本模块发出的事件，防止自激
      if (envelope.meta.source === EXECUTION_STORE_SOURCE) {
        return
      }

      if (_ORDER_CHANGE_ACTIONS.has(envelope.meta.action)) {
        logger.info('[executionStore] DataBridge orders event received', {
          action: envelope.meta.action,
          traceId: envelope.meta.traceId,
          source: envelope.meta.source,
        })

        // 订单变更触发刷新以同步最新状态
        _debouncedRefresh(envelope)
      }
    },
  )

  logger.info('[executionStore] DataBridge subscriptions initialized')

  return _destroySubscriptions
}

function _destroySubscriptions(): void {
  if (_debounceTimer) {
    clearTimeout(_debounceTimer)
    _debounceTimer = null
  }
  _unsubscribeSignals?.()
  _unsubscribeOrders?.()
  _unsubscribeSignals = null
  _unsubscribeOrders = null
  logger.info('[executionStore] DataBridge subscriptions destroyed')
}

/**
 * @module store/helpers/withOptimisticUpdate
 * @lifecycle @Global
 * @description 乐观更新事务边界工具 — 提供统一的 snapshot → apply → rollback 三步流程
 *
 * 解决问题：
 * - tradingStore.ts:173 有局部 snapshot，但全项目无统一 Rollback 机制
 * - 各 Store 各自实现乐观更新，代码重复且行为不一致
 *
 * 使用方式：
 *
 * ```ts
 * import { withOptimisticUpdate } from '@/store/helpers/withOptimisticUpdate'
 *
 * // 在 Store action 中
 * addOrder: async (order) => {
 *   return withOptimisticUpdate(
 *     get,
 *     set,
 *     (draft) => { draft.orders.push(order) },  // 乐观应用
 *     async () => { await dataBridge.forward(envelope) },  // 实际写入
 *     'addOrder',
 *   )
 * }
 * ```
 */

import { getLogger } from '@/lib/logger'

const logger = getLogger()

export interface OptimisticUpdateResult<T> {
  success: boolean
  data?: T
  error?: string
  rolledBack: boolean
}

/**
 * 执行乐观更新事务
 *
 * @param getStore Store 的 get 函数
 * @param setStore Store 的 set 函数
 * @param applyFn 乐观应用函数（修改 draft 状态，立即反映到 UI）
 * @param commitFn 实际提交函数（异步写入 DB/API）
 * @param operationName 操作名称（用于日志）
 * @returns 事务结果
 */
export async function withOptimisticUpdate<TState, TResult>(
  getStore: () => TState,
  setStore: (updater: (state: TState) => TState) => void,
  applyFn: (state: TState) => void,
  commitFn: () => Promise<TResult>,
  operationName: string,
): Promise<OptimisticUpdateResult<TResult>> {
  // Step 1: 保存快照（深拷贝当前状态用于回滚）
  const snapshot = structuredClone(getStore())

  logger.info(`[withOptimisticUpdate] "${operationName}" — 保存快照`)

  // Step 2: 乐观应用变更
  try {
    setStore((state) => {
      applyFn(state)
      return state
    })
    logger.debug(`[withOptimisticUpdate] "${operationName}" — 乐观应用完成`)
  } catch (err) {
    logger.error(`[withOptimisticUpdate] "${operationName}" — 乐观应用失败`, {
      error: err instanceof Error ? err.message : String(err),
    })
    return {
      success: false,
      error: `乐观应用失败: ${err instanceof Error ? err.message : String(err)}`,
      rolledBack: false,
    }
  }

  // Step 3: 实际提交
  try {
    const result = await commitFn()
    logger.info(`[withOptimisticUpdate] "${operationName}" — 提交成功`)
    return {
      success: true,
      data: result,
      rolledBack: false,
    }
  } catch (err) {
    // Step 3b: 提交失败 → 回滚到快照
    const errorMsg = err instanceof Error ? err.message : String(err)
    logger.error(`[withOptimisticUpdate] "${operationName}" — 提交失败，开始回滚`, {
      error: errorMsg,
    })

    try {
      setStore(() => snapshot)
      logger.info(`[withOptimisticUpdate] "${operationName}" — 回滚完成`)
    } catch (rollbackErr) {
      logger.error(`[withOptimisticUpdate] "${operationName}" — 回滚失败!`, {
        error: rollbackErr instanceof Error ? rollbackErr.message : String(rollbackErr),
      })
    }

    return {
      success: false,
      error: errorMsg,
      rolledBack: true,
    }
  }
}

/**
 * 轻量级快照工具（不使用 structuredClone，适用于大型状态）
 * 仅保存指定字段的浅拷贝
 */
export function snapshotFields<TState, K extends keyof TState>(
  state: TState,
  fields: K[],
): Pick<TState, K> {
  const snap: Partial<Pick<TState, K>> = {}
  for (const f of fields) {
    snap[f] = Array.isArray(state[f])
      ? [...(state[f] as unknown[])] as TState[K]
      : typeof state[f] === 'object' && state[f] !== null
        ? { ...state[f] } as TState[K]
        : state[f]
  }
  return snap as Pick<TState, K>
}

/**
 * 恢复指定字段（配合 snapshotFields 使用）
 */
export function restoreFields<TState, K extends keyof TState>(
  setStore: (updater: (state: TState) => TState) => void,
  snapshot: Pick<TState, K>,
): void {
  setStore((state) => {
    return { ...state, ...snapshot }
  })
}

/**
 * @module holdingsStore
 * @lifecycle @Global
 * @description 交易持仓状态管理。从 HoldingsPage.tsx 的 useReducer 迁移至 Zustand，
 * 支持跨组件（如 TradingApp 的 CoreResourcePanel）共享持仓状态。
 *
 * @compliance
 * - 所有颜色值从 @/constants/trade.constants 引用
 * - 所有枚举值从 @/constants/trade.constants 引用
 * - 魔法值禁止出现在 actions 中
 */

import { create } from 'zustand'
import {
  TRADE_DIRECTION,
  PAGINATION_DEFAULTS,
  FILTER_DEFAULTS,
} from '@/constants/trade.constants'
import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION, ENVELOPE_TARGET, MODULE_ID } from '@/config/dbConfig'
import type {
  HoldingItem,
  FilterState,
  PaginationState,
  HoldingsLoadingState,
  TradeModalState,
  HoldingsQueryParams,
} from '@/types/modules/trade.types'
import type { HoldingAction } from '@/constants/trade.constants'
import { HTTP_OK, HTTP_INTERNAL_ERROR } from '@/config/mathConstants'

const logger = getLogger()

// ============================================================
// 工具函数
// ============================================================

function getDefaultDateRange(): { start: string; end: string } {
  const end = new Date()
  const start = new Date()
  start.setDate(start.getDate() - FILTER_DEFAULTS.DEFAULT_DATE_RANGE_DAYS)
  return {
    start: start.toISOString().slice(0, 10),
    end: end.toISOString().slice(0, 10),
  }
}

const defaultDates = getDefaultDateRange()

// ============================================================
// Store 接口
// ============================================================

interface HoldingsState {
  /** 持仓数据 */
  data: HoldingItem[]
  /** 筛选条件 */
  filter: FilterState
  /** 分页状态 */
  pagination: PaginationState
  /** 加载状态 */
  loading: HoldingsLoadingState
  /** 交易弹窗 */
  modal: TradeModalState

  // Actions
  setData: (list: HoldingItem[], total: number) => void
  setFilter: (partial: Partial<FilterState>) => void
  setPage: (page: number) => void
  setPageSize: (pageSize: number) => void
  setLoading: (partial: Partial<HoldingsLoadingState>) => void
  openModal: (holding: HoldingItem, action: HoldingAction) => void
  closeModal: () => void
  resetFilter: () => void
  fetchData: (params: HoldingsQueryParams) => Promise<{ code: number; message: string }>
  executeTrade: (opts: { code: string; action: HoldingAction; quantity: number }) => Promise<{ success: boolean; message: string }>
  exportCSV: (params: HoldingsQueryParams) => Promise<void>
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  data: [] as HoldingItem[],
  filter: {
    startDate: defaultDates.start,
    endDate: defaultDates.end,
    direction: TRADE_DIRECTION.ALL,
    keyword: '',
  } as FilterState,
  pagination: {
    page: PAGINATION_DEFAULTS.DEFAULT_PAGE,
    pageSize: PAGINATION_DEFAULTS.DEFAULT_PAGE_SIZE,
    total: 0,
  } as PaginationState,
  loading: {
    isListLoading: false,
    isActionLoading: false,
    isExporting: false,
  } as HoldingsLoadingState,
  modal: {
    open: false,
    action: null,
    holding: null,
  } as TradeModalState,
}

// ============================================================
// Store
// ============================================================

export const useHoldingsStore = create<HoldingsState>((set) => ({
  ...initialState,

  setData: (list, total) =>
    set((state) => ({
      data: list,
      pagination: { ...state.pagination, total },
    })),

  setFilter: (partial) =>
    set((state) => ({
      filter: { ...state.filter, ...partial },
      pagination: { ...state.pagination, page: PAGINATION_DEFAULTS.DEFAULT_PAGE },
    })),

  setPage: (page) =>
    set((state) => ({
      pagination: { ...state.pagination, page },
    })),

  setPageSize: (pageSize) =>
    set((state) => ({
      pagination: {
        ...state.pagination,
        pageSize,
        page: PAGINATION_DEFAULTS.DEFAULT_PAGE,
      },
    })),

  setLoading: (partial) =>
    set((state) => ({
      loading: { ...state.loading, ...partial },
    })),

  openModal: (holding, action) =>
    set({
      modal: { open: true, holding, action },
    }),

  closeModal: () =>
    set({
      modal: { open: false, holding: null, action: null },
    }),

  resetFilter: () => {
    const resetDates = getDefaultDateRange()
    logger.info('[holdingsStore] Filter reset', { resetDates })
    set((state) => ({
      filter: {
        startDate: resetDates.start,
        endDate: resetDates.end,
        direction: TRADE_DIRECTION.ALL,
        keyword: '',
      },
      pagination: { ...state.pagination, page: PAGINATION_DEFAULTS.DEFAULT_PAGE },
    }))
  },

  fetchData: async (params) => {
    set((s) => ({ loading: { ...s.loading, isListLoading: true } }))
    try {
      await dataBridge.forward({
        meta: {
          traceId: `holdings-fetch-${Date.now()}`,
          source: MODULE_ID.holdingsStore,
          target: ENVELOPE_TARGET.tradinghub,
          action: ENVELOPE_ACTION.loadHoldingsData,
          timestamp: Date.now(),
        },
        payload: params,
      })
      return { code: HTTP_OK, message: 'OK' }
    } catch (error) {
      logger.error('[holdingsStore] fetchData failed', { error: String(error) })
      return { code: HTTP_INTERNAL_ERROR, message: String(error) }
    } finally {
      set((s) => ({ loading: { ...s.loading, isListLoading: false } }))
    }
  },

  executeTrade: async (_opts) => {
    logger.info('[holdingsStore] executeTrade called', { opts: _opts })
    return { success: true, message: 'Trade executed' }
  },

  exportCSV: async (_params) => {
    set((s) => ({ loading: { ...s.loading, isExporting: true } }))
    try {
      logger.info('[holdingsStore] exportCSV started')
    } finally {
      set((s) => ({ loading: { ...s.loading, isExporting: false } }))
    }
  },
}))

// ============================================================
// 工具函数：构建查询参数
// ============================================================

/** 从当前 store 状态构建 HoldingsQueryParams */
export function buildHoldingsParams(): HoldingsQueryParams {
  const state = useHoldingsStore.getState()
  return {
    page: state.pagination.page,
    pageSize: state.pagination.pageSize,
    startDate: state.filter.startDate,
    endDate: state.filter.endDate,
    direction: state.filter.direction,
    keyword: state.filter.keyword,
  }
}

// ============================================================
// DataBridge 订阅生命周期
// ============================================================
// 由组件层 useEffect 调用 init，返回的 cleanup 函数中调用 destroy
// 避免模块级副作用导致的 HMR 重复订阅和内存泄漏

let _unsubscribeTrading: (() => void) | null = null

/** 初始化 DataBridge 交易通道订阅，返回 cleanup 函数 */
export function initHoldingsStoreSubscriptions(): () => void {
  if (_unsubscribeTrading) {
    logger.warn('[holdingsStore] Subscriptions already initialized, skipping')
    return _unsubscribeTrading
  }

  _unsubscribeTrading = dataBridge.subscribe('trading', (envelope) => {
    if (envelope.meta.action === ENVELOPE_ACTION.tradeActionExecuted) {
      logger.info('[holdingsStore] DataBridge event received: tradeActionExecuted', {
        traceId: envelope.meta.traceId,
        source: envelope.meta.source,
      })
    }
    if (envelope.meta.action === ENVELOPE_ACTION.holdingsDataLoaded) {
      logger.info('[holdingsStore] DataBridge event received: holdingsDataLoaded', {
        traceId: envelope.meta.traceId,
      })
    }
  })

  return () => {
    _unsubscribeTrading?.()
    _unsubscribeTrading = null
    logger.info('[holdingsStore] DataBridge subscriptions destroyed')
  }
}

// @module hotSectorStore
// @lifecycle @Analysis
// 分析舱-热门板块策略页面的全局状态管理（Zustand）。
// expandedSymbol 保留为页面本地 UI 状态。
//
// 管理范围：
// - 数据层：scores / loading / error
// - 引擎调用：通过 fetchScores 调用 hotSectorAnalyzer
//
// @compliance DF-002 合规：所有引擎调用经由 Store action 分发
import { create } from 'zustand'
import type { HotSectorScore, HotSectorAnalyzerInput } from '@/services/scoring/hotSectorAnalyzer'
import { analyze as analyzeHotSector } from '@/services/scoring/hotSectorAnalyzer'
import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION } from '@/config/dbConfig'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'

const logger = getLogger()

// ============================================================
// 默认样本数据（股票池为空时的回退数据）
// ============================================================

const HOT_SECTOR_DEFAULT_SAMPLES: HotSectorAnalyzerInput[] = [
  {
