 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { SECTORS_SKILL_RANKED, type SectorSkillAnalysis } from '@/data/sectorSkillData'
import type { IndustryScore, ResearchLog } from '@/data/types'
