}

/**
 * @module multiFactorScreeningStore
 * @description 多因子筛选器 Zustand Store（DA-007 四步集成合约：第 2 步 Store）。
 * 负责状态管理、模板持久化、调用 Engine 执行筛选。
 */

import { create } from 'zustand'
import { createStorage } from '@/lib/localStorageManager'
import { getLogger } from '@/lib/logger'
import type {
  ScreeningConditionGroup,
  ScreeningCriterion,
  ScreeningLogic,
  ScreeningResultItem,
  ScreeningTemplate,
} from '@/types/modules/screening.types'
import {
  loadScreenableStocks,
  runScreening,
  createTemplateFromGroups,
  exportScreeningResults,
} from '@/services/screening/multiFactorScreeningEngine'
import {
  MULTI_FACTOR_SCREENING_DEFAULT_LOGIC,
  MULTI_FACTOR_SCREENING_FACTORS,
  MULTI_FACTOR_SCREENING_STORAGE_KEY,
  MULTI_FACTOR_SCREENING_TEMPLATE_NAME_MAX_LENGTH,
  MULTI_FACTOR_SCREENING_CSV_FILENAME_PREFIX,
} from '@/config/multiFactorScreeningConfig'

const logger = getLogger()
const storage = createStorage('multiFactorScreening')

function generateId(prefix = 'id'): string {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`
}

function createDefaultCriterion(): ScreeningCriterion {
  const meta = MULTI_FACTOR_SCREENING_FACTORS[0]!
  return {
    id: generateId('criterion'),
    factor: meta.factor,
    operator: meta.defaultOperator,
    value: meta.defaultValue,
  }
}

function createDefaultGroup(): ScreeningConditionGroup {
  return {
    id: generateId('group'),
    logic: MULTI_FACTOR_SCREENING_DEFAULT_LOGIC,
    criteria: [createDefaultCriterion()],
  }
}

export interface MultiFactorScreeningState {
  conditionGroups: ScreeningConditionGroup[]
  results: ScreeningResultItem[]
  loading: boolean
  error: string | null
  templates: ScreeningTemplate[]

  // Actions: 条件组编辑
  addGroup: () => void
  removeGroup: (groupId: string) => void
  setGroupLogic: (groupId: string, logic: ScreeningLogic) => void
  addCriterion: (groupId: string) => void
  removeCriterion: (groupId: string, criterionId: string) => void
  updateCriterion: (
    groupId: string,
    criterionId: string,
    updates: Partial<Omit<ScreeningCriterion, 'id'>>,
  ) => void
  setGroups: (groups: ScreeningConditionGroup[]) => void
  resetGroups: () => void

  // Actions: 筛选执行
  runScreening: () => Promise<void>
  clearResults: () => void

  // Actions: 模板持久化
  saveTemplate: (name: string, description?: string) => ScreeningTemplate | null
  loadTemplate: (templateId: string) => void
  deleteTemplate: (templateId: string) => void
  loadSavedTemplates: () => void

  // Actions: 导出
  exportResults: () => void
}

function persistTemplates(templates: ScreeningTemplate[]): void {
  try {
    storage.set(MULTI_FACTOR_SCREENING_STORAGE_KEY, templates)
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error('[multiFactorScreeningStore] 模板持久化失败', { error: message })
  }
}

export const useMultiFactorScreeningStore = create<MultiFactorScreeningState>((set, get) => ({
  conditionGroups: [createDefaultGroup()],
  results: [],
  loading: false,
  error: null,
  templates: [],

  addGroup: () => {
    set((state) => ({ conditionGroups: [...state.conditionGroups, createDefaultGroup()] }))
  },

  removeGroup: (groupId) => {
    set((state) => ({
      conditionGroups: state.conditionGroups.filter((group) => group.id !== groupId),
    }))
  },

  setGroupLogic: (groupId, logic) => {
    set((state) => ({
      conditionGroups: state.conditionGroups.map((group) =>
        group.id === groupId ? { ...group, logic } : group,
      ),
    }))
  },

  addCriterion: (groupId) => {
    set((state) => ({
      conditionGroups: state.conditionGroups.map((group) =>
        group.id === groupId
          ? { ...group, criteria: [...group.criteria, createDefaultCriterion()] }
          : group,
      ),
    }))
  },

  removeCriterion: (groupId, criterionId) => {
    set((state) => ({
      conditionGroups: state.conditionGroups.map((group) =>
        group.id === groupId
          ? { ...group, criteria: group.criteria.filter((c) => c.id !== criterionId) }
          : group,
      ),
    }))
  },

  updateCriterion: (groupId, criterionId, updates) => {
    set((state) => ({
      conditionGroups: state.conditionGroups.map((group) =>
        group.id === groupId
          ? {
              ...group,
              criteria: group.criteria.map((criterion) =>
                criterion.id === criterionId ? { ...criterion, ...updates } : criterion,
              ),
            }
          : group,
      ),
    }))
  },

  setGroups: (groups) => set({ conditionGroups: groups }),

  resetGroups: () => set({ conditionGroups: [createDefaultGroup()], results: [], error: null }),

  runScreening: async () => {
    set({ loading: true, error: null })
    try {
      const stocks = await loadScreenableStocks()
      const result = runScreening(stocks, get().conditionGroups)
      set({ results: result.items, loading: false })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[multiFactorScreeningStore] 筛选失败', { error: message })
      set({ error: message, loading: false })
    }
  },

  clearResults: () => set({ results: [], error: null }),

  saveTemplate: (name, description) => {
    const trimmed = name.trim()
    if (trimmed.length === 0 || trimmed.length > MULTI_FACTOR_SCREENING_TEMPLATE_NAME_MAX_LENGTH) {
      set({ error: `模板名称长度需在 1-${MULTI_FACTOR_SCREENING_TEMPLATE_NAME_MAX_LENGTH} 之间` })
      return null
    }

    const template = createTemplateFromGroups(trimmed, get().conditionGroups, description)
    const templates = [...get().templates, template]
    set({ templates, error: null })
    persistTemplates(templates)
    return template
  },

  loadTemplate: (templateId) => {
    const template = get().templates.find((t) => t.id === templateId)
    if (!template) {
      set({ error: `未找到模板 ${templateId}` })
      return
    }
    set({ conditionGroups: template.groups, results: [], error: null })
  },

  deleteTemplate: (templateId) => {
    const templates = get().templates.filter((t) => t.id !== templateId)
    set({ templates })
    persistTemplates(templates)
  },

  loadSavedTemplates: () => {
    try {
      const raw = storage.get<ScreeningTemplate[]>(MULTI_FACTOR_SCREENING_STORAGE_KEY)
      set({ templates: raw ?? [] })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[multiFactorScreeningStore] 读取模板失败', { error: message })
      set({ templates: [] })
    }
  },

  exportResults: () => {
    exportScreeningResults(get().results, MULTI_FACTOR_SCREENING_CSV_FILENAME_PREFIX)
  },
}))

/**
 * @module orderStore
 * @lifecycle @Global
 * @description 交易总账本 —— 订单域的唯一可信源（Single Source of Truth）。
 * 统一管理全部订单、当前持仓、已实现盈亏与未实现盈亏，
 * 取代原先分散在 positionStore / holdingsStore / orderStore 中的重复计算。
 *
 * @compliance
 * - isRefreshing 锁防止并发刷新
 * - 失败时快照回滚，保留旧数据不被清空
 * - 所有写操作通过 dataBridge.forward() 走信封协议
 * - 订阅 STORE_NAME.orders 频道，source 过滤防自激，100ms 去抖合并
 * - 保持 useOrderStore 导出名，向后兼容现有引用
 *
 * @see docs/《V9核心数据字典与类型定义（整合版）》.md
 */

import { create } from 'zustand'
import { subscribeWithSelector } from 'zustand/middleware'
import { getLogger } from '@/lib/logger'
import { dataLayer } from '@/data/dataLayer'
import { dataBridge } from '@/core/databridge'
import { EnvelopeFactory } from '@/core/envelope'
import { refreshCoordinator } from '@/core/refreshCoordinator'
import {
  ENVELOPE_ACTION,
  ENVELOPE_TARGET,
  MODULE_ID,
  STORE_NAME,
  type EnvelopeAction,
} from '@/config/dbConfig'
import type { Order } from '@/data/types'
import type { StandardEnvelope } from '@/core/envelope'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import {
  buildTradePairs,
  buildPositions,
  type SymbolTradePair,
  type PositionItem,
} from '@/services/trading/positionComputer'
import { computePnLSummary, type PnLSummary } from '@/services/trading/pnlComputer'
import { computeRiskMetrics, type RiskMetrics } from '@/services/trading/riskComputer'

const logger = getLogger()

// ============================================================
// 类型定义（从计算模块重新导出，保持向后兼容）
// ============================================================

// 重新导出类型，保持向后兼容性
export type {
  MatchedTradePair,
  SymbolTradePair,
  PositionItem,
} from '@/services/trading/positionComputer'

// 重新导出规范 TradePair 类型（来自 types 层零依赖定义）
export type { TradePair } from '@/services/trading/tradeReviewAI.types'

export type {
  PnLSummary,
} from '@/services/trading/pnlComputer'

export type {
  RiskMetrics,
} from '@/services/trading/riskComputer'

/**
 * OrderStore 状态接口 —— 订单域唯一可信源。
 * 包含订单原始数据、派生持仓、派生盈亏汇总。
 */
export interface OrderState {
  // ---- 核心数据 ----
  /** 全部订单列表（原始数据） */
  orders: Order[]
  /** 当前持仓（按 symbol 聚合，净持仓 > 0 的标的） */
  positions: PositionItem[]
  /** 已实现盈亏总金额（元） */
  realizedPnL: number
  /** 未实现盈亏总金额（元）—— 无行情时为 0 */
  unrealizedPnL: number
  /** 按 symbol 聚合的交易对（派生） */
  tradePairs: SymbolTradePair[]
  /** 盈亏汇总（派生） */
  pnlSummary: PnLSummary
  /** 风险指标（派生） */
  riskMetrics: RiskMetrics

  // ---- 加载状态 ----
  /** 是否正在加载（首次加载） */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 是否正在刷新中（用于并发锁） */
  isRefreshing: boolean
  /** 最后更新时间戳 */
  lastUpdated: number

  // ---- Actions ----
  /**
   * 从 dataLayer 全量刷新订单、持仓与盈亏数据。
   * 具备 isRefreshing 并发锁，失败时回滚到旧快照。
   */
  refresh: () => Promise<void>
  /**
   * 内部刷新方法，实际执行刷新逻辑（由 refresh() 和 coordinator 调用）。
   */
  _doRefresh: () => Promise<void>
  /**
   * 新增订单。通过 dataBridge.forward() 走信封协议写入，
   * 写入后由订阅机制异步触发刷新。
   * @param order - 订单数据（不含 id 和 createdAt，由系统生成）
   * @returns 写入结果，成功时包含完整订单
   */
  addOrder: (order: Omit<Order, 'id' | 'createdAt'>) => Promise<{ success: boolean; data?: Order; error?: string }>
  /**
   * 更新订单。通过 dataBridge.forward() 走信封协议。
   * @param id - 订单 ID
   * @param updates - 要更新的字段
   */
  updateOrder: (id: string, updates: Partial<Order>) => Promise<{ success: boolean; error?: string }>
  /**
   * 删除订单。通过 dataBridge.forward() 走信封协议。
   * @param id - 订单 ID
   */
  deleteOrder: (id: string) => Promise<{ success: boolean; error?: string }>
  /**
   * 获取指定股票的持仓信息（selector 风格辅助函数）。
   * @param symbol - 股票代码
   * @returns 持仓项，若不存在则返回 null
   */
  getPosition: (symbol: string) => PositionItem | null
  /**
   * 重置 store 到初始空状态。
   */
  reset: () => void
}

// ============================================================
// 初始状态
// ============================================================

const initialState: Omit<
  OrderState,
  'refresh' | '_doRefresh' | 'addOrder' | 'updateOrder' | 'deleteOrder' | 'getPosition' | 'reset'
> = {
  orders: [],
  positions: [],
  realizedPnL: 0,
  unrealizedPnL: 0,
  tradePairs: [],
  pnlSummary: {
    totalRealizedPnl: 0,
    totalUnrealizedPnl: 0,
    winRate: 0,
    profitFactor: 0,
    totalTrades: 0,
    profitTrades: 0,
    lossTrades: 0,
    monthlyPnL: [],
    dailyCurve: [],
  },
  riskMetrics: {
    var95: 0,
    varLevel: 'low',
    maxDrawdown: 0,
    volatility: 0,
    sharpeRatio: 0,
    betaEstimate: 0,
    concentration: 0,
    alerts: [],
  },
  loading: true,
  error: null,
  isRefreshing: false,
  lastUpdated: 0,
}

// ============================================================
// 工具函数
// ============================================================

/** 生成 traceId */
function createTraceId(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
}

// 计算函数已从以下模块导入：
// - buildTradePairs, buildPositions, type MatchedTradePair, type TradePair, type PositionItem
//   from '@/services/trading/positionComputer'
// - computePnLSummary, type PnLSummary from '@/services/trading/pnlComputer'
// - computeRiskMetrics, type RiskMetrics from '@/services/trading/riskComputer'

// ============================================================
// Store
// ============================================================

/**
 * 订单域全局 Store —— 交易总账本。
 * 统一管理订单、持仓、盈亏，作为订单域唯一可信源。
 */
export const useOrderStore = create<OrderState>()(
  subscribeWithSelector((set, get) => ({
    ...initialState,

    // ----------------------------------------------------------
    // refresh —— 全量刷新
    // ----------------------------------------------------------

  /**
   * 从 dataLayer 全量刷新订单数据，并重新计算持仓与盈亏。
   *
   * @remarks
   * - 具备 isRefreshing 并发锁，防止重复调用
   * - 失败时保留旧数据快照（仅更新 error / loading 状态）
   * - 同时更新 positions、realizedPnL、unrealizedPnL 等派生数据
   */
  refresh: async () => {
    // 使用 RefreshCoordinator 协调跨 Store 刷新
    // isRefreshing 时不再直接 return，而是 await 正在进行的刷新 Promise
    // 这样 disciplineStore 调用 orderStore.getState().refresh() 时，
    // 如果 orderStore 正在刷新，会等待完成后使用最新数据
    await refreshCoordinator.coordinateRefresh('orderStore', () =>
      get()._doRefresh(),
    )
  },

  /**
   * 内部刷新方法，实际执行刷新逻辑。
   * 由 refresh() 和 RefreshCoordinator 共同调用。
   */
  _doRefresh: async () => {
    const state = get()

    // 保存旧数据快照，用于失败回滚
    const snapshot = {
      orders: state.orders,
      positions: state.positions,
      realizedPnL: state.realizedPnL,
      unrealizedPnL: state.unrealizedPnL,
      tradePairs: state.tradePairs,
      pnlSummary: state.pnlSummary,
      riskMetrics: state.riskMetrics,
      lastUpdated: state.lastUpdated,
    }

    set({ isRefreshing: true, loading: state.orders.length === 0, error: null })

    try {
      logger.info('[orderStore] refresh 开始')
      const orders = await dataLayer.orders.list()

      // 计算派生数据
      const tradePairs = buildTradePairs(orders)
      const pnlSummary = computePnLSummary(tradePairs)
      const positions = buildPositions(tradePairs)
      const riskMetrics = computeRiskMetrics(tradePairs, pnlSummary, positions)

      set({
        orders,
        positions,
        tradePairs,
        pnlSummary,
        riskMetrics,
        realizedPnL: pnlSummary.totalRealizedPnl,
        unrealizedPnL: pnlSummary.totalUnrealizedPnl,
        loading: false,
        error: null,
        isRefreshing: false,
        lastUpdated: Date.now(),
      })

      logger.info('[orderStore] refresh 完成', {
        orders: orders.length,
        positions: positions.length,
        realizedPnL: pnlSummary.totalRealizedPnl,
      })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[orderStore] refresh 失败，回滚到旧快照', { error: message })

      // 失败回滚：保留旧数据，仅更新错误和加载状态
      set({
        ...snapshot,
        loading: false,
        error: message,
        isRefreshing: false,
      })
    }
  },

  // ----------------------------------------------------------
  // addOrder —— 新增订单
  // ----------------------------------------------------------

  /**
   * 新增订单。通过 dataBridge.forward() 走信封协议写入 DB，
   * 写入成功后由 STORE_NAME.orders 频道订阅机制异步触发 refresh。
   *
   * @param order - 订单数据（不含 id 和 createdAt）
   * @returns 写入结果，成功时 data 为完整订单（含 id/createdAt）
   */
  addOrder: async (order) => {
    logger.info('[orderStore] addOrder', { symbol: order.symbol, direction: order.direction })

    try {
      const fullOrder: Order = {
        ...order,
        id: createTraceId('ord'),
        createdAt: Date.now(),
      }

      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.orderstore,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.insertOrder,
          traceId: createTraceId('os-add'),
        },
        fullOrder,
      )

      await dataBridge.forward(envelope)

      logger.info('[orderStore] addOrder 成功', { id: fullOrder.id, symbol: fullOrder.symbol })
      withBroadcast(EVENT_NAMES.ORDERS_CHANGED, { action: 'add', id: fullOrder.id, symbol: fullOrder.symbol })
      return { success: true, data: fullOrder }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[orderStore] addOrder 失败', { error: message, symbol: order.symbol })
      return { success: false, error: message }
    }
  },

  // ----------------------------------------------------------
  // updateOrder —— 更新订单
  // ----------------------------------------------------------

  /**
   * 更新订单。通过 dataBridge.forward() 走信封协议。
   *
   * @param id - 订单 ID
   * @param updates - 要更新的字段（不能修改 id 和 createdAt）
   */
  updateOrder: async (id, updates) => {
    logger.info('[orderStore] updateOrder', { id, fields: Object.keys(updates) })

    try {
      const payload = { id, ...updates }

      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.orderstore,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.updateOrder,
          traceId: createTraceId('os-upd'),
        },
        payload,
      )

      await dataBridge.forward(envelope)

      logger.info('[orderStore] updateOrder 成功', { id })
      withBroadcast(EVENT_NAMES.ORDERS_CHANGED, { action: 'update', id })
      return { success: true }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[orderStore] updateOrder 失败', { error: message, id })
      return { success: false, error: message }
    }
  },

  // ----------------------------------------------------------
  // deleteOrder —— 删除订单
  // ----------------------------------------------------------

  /**
   * 删除订单。通过 dataBridge.forward() 走信封协议。
   *
   * @param id - 订单 ID
   */
  deleteOrder: async (id) => {
    logger.info('[orderStore] deleteOrder', { id })

    try {
      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.orderstore,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.deleteOrder,
          traceId: createTraceId('os-del'),
        },
        { id },
      )

      await dataBridge.forward(envelope)

      logger.info('[orderStore] deleteOrder 成功', { id })
      withBroadcast(EVENT_NAMES.ORDERS_CHANGED, { action: 'delete', id })
      return { success: true }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[orderStore] deleteOrder 失败', { error: message, id })
      return { success: false, error: message }
    }
  },

  // ----------------------------------------------------------
  // getPosition —— 单标的持仓 selector
  // ----------------------------------------------------------

  /**
   * 获取指定股票的持仓信息。
   *
   * @param symbol - 股票代码
   * @returns 持仓项，若不存在或已清仓则返回 null
   */
  getPosition: (symbol) => {
    const { positions } = get()
    return positions.find((p) => p.symbol === symbol) ?? null
  },

  // ----------------------------------------------------------
  // reset —— 重置
  // ----------------------------------------------------------

  /**
   * 重置 store 到初始空状态。
   * 通常用于登出/切换账户等场景。
   */
  reset: () => {
    logger.info('[orderStore] reset')
    set({ ...initialState })
    withBroadcast(EVENT_NAMES.ORDERS_CHANGED, { action: 'reset' })
  },
}))
)

// ============================================================
// DataBridge 订阅生命周期
// ============================================================

/**
 * 本模块 source 标识，用于订阅时 source 过滤，防止自激（自己发的事件自己又处理）。
 *
 * @remarks
 * 订阅 STORE_NAME.orders 频道，source 为 MODULE_ID.orderstore。
 * 写操作发出的事件 meta.source === 此值，订阅回调中据此过滤跳过。
 */
const ORDER_STORE_SOURCE = MODULE_ID.orderstore

/** 去抖合并窗口（毫秒）：短时间内多次变更合并为一次 refresh */
const DEBOUNCE_MS = 100

let _unsubscribeOrders: (() => void) | null = null
let _debounceTimer: ReturnType<typeof setTimeout> | null = null

/** 需要触发刷新的订单相关 action 集合 */
const _ORDER_CHANGE_ACTIONS = new Set<EnvelopeAction>([
  ENVELOPE_ACTION.insertOrder,
  ENVELOPE_ACTION.updateOrder,
  ENVELOPE_ACTION.deleteOrder,
  ENVELOPE_ACTION.tradeActionExecuted,
])

/**
 * 去抖执行 refresh，100ms 内多次调用合并为一次。
 *
 * @param envelope - 触发去抖的信封（用于日志追踪）
 */
function _debouncedRefresh(envelope: StandardEnvelope): void {
  if (_debounceTimer) {
    clearTimeout(_debounceTimer)
  }
  _debounceTimer = setTimeout(() => {
    _debounceTimer = null
    logger.info('[orderStore] Debounced refresh triggered', {
      traceId: envelope.meta.traceId,
      action: envelope.meta.action,
      source: envelope.meta.source,
    })
    // 通过 coordinator 协调刷新，确保跨 Store 数据一致性
    void refreshCoordinator.coordinateRefresh('orderStore', () =>
      useOrderStore.getState()._doRefresh(),
    )
  }, DEBOUNCE_MS)
}

/**
 * 初始化 OrderStore 的 DataBridge 订阅。
 *
 * 订阅 STORE_NAME.orders 频道，监听以下 action 并触发去抖刷新：
 * - insertOrder
 * - updateOrder
 * - deleteOrder
 * - tradeActionExecuted
 *
 * 同时做 source 过滤：跳过 source 为 'orderstore' 的事件，防止自激。
 *
 * @returns 清理函数，调用后取消所有订阅并清理定时器
 *
 * @example
 * ```ts
 * // 在 App 根组件中初始化
 * useEffect(() => {
 *   const cleanup = initOrderStoreSubscriptions()
 *   return cleanup
 * }, [])
 * ```
 */
export function initOrderStoreSubscriptions(): () => void {
  if (_unsubscribeOrders) {
    logger.warn('[orderStore] Subscriptions already initialized, skipping')
    return _unsubscribeOrders
  }

  _unsubscribeOrders = dataBridge.subscribe(
    STORE_NAME.orders,
    (envelope) => {
      // priority: high — 交易执行需即时响应

      // source 过滤：跳过本模块发出的事件，防止自激
      if (envelope.meta.source === ORDER_STORE_SOURCE) {
        return
      }

      if (_ORDER_CHANGE_ACTIONS.has(envelope.meta.action)) {
        logger.info('[orderStore] DataBridge orders event, scheduling debounced refresh', {
          action: envelope.meta.action,
          traceId: envelope.meta.traceId,
          source: envelope.meta.source,
        })
        _debouncedRefresh(envelope)
      }
    },
  )

  logger.info('[orderStore] DataBridge orders subscriptions initialized')

  /** 清理函数：取消订阅 + 清除去抖定时器 */
  return () => {
    if (_debounceTimer) {
      clearTimeout(_debounceTimer)
      _debounceTimer = null
    }
    _unsubscribeOrders?.()
    _unsubscribeOrders = null
    logger.info('[orderStore] DataBridge subscriptions destroyed')
  }
}

/**
 * @module positionStore
 * @lifecycle @Global
 * @description 仓位控制状态管理。管理总资产、可用资金、仓位比例及持仓明细，
 * 数据从 orderStore 派生，不再直接读取 dataLayer.orders.list()，避免与 orderStore 重复读取。
 *
 * @compliance
 * - 所有颜色值从 PIE_COLORS 常量引用
 * - 所有魔法值禁止出现在 actions 中
 * - 订阅 orderStore 内存状态，200ms 去抖合并 + isRefreshing 防重入
 * - 遵循现有 Zustand Store 风格
 *
 * @see docs/《V9核心数据字典与类型定义（整合版）》.md
 * @see src/config/chartColors.ts - PIE_CHART_PALETTE
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { eventBus } from '@/lib/eventBus'
import { getOrders } from '@/services/trading/tradingService'
import type { Order } from '@/data/types'
import { PIE_CHART_PALETTE } from '@/config/chartColors'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'

const logger = getLogger()

// ============================================================
// 常量
// ============================================================

/** 饼图颜色调色板（从 chartColors 统一引用） */
export const PIE_COLORS = [...PIE_CHART_PALETTE] as const

// ============================================================
// 类型定义
// ============================================================

/** 单条持仓明细 */
export interface PositionHoldingItem {
  symbol: string
  name: string
  value: number
  /** 占总投资比例 % (0-100) */
  ratio: number
  /** 饼图颜色（由 PIE_COLORS 按索引分配） */
  color: string
  /** 持仓方向 */
  direction: 'buy' | 'sell'
}

// ============================================================
// Store 接口
// ============================================================

interface PositionState {
  /** 总资产（估算值） */
  totalValue: number
  /** 可用资金 */
  availableFunds: number
  /** 仓位比例 (0-100) */
  positionRatio: number
  /** 持仓明细 */
  holdings: PositionHoldingItem[]
  /** 加载状态 */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 最后更新时间戳 */
  lastUpdated: number | null

  // Actions
  refresh: () => Promise<void>
  recomputeFromOrders: (orders: Order[]) => void
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
  reset: () => void
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  totalValue: 0,
  availableFunds: 0,
  positionRatio: 0,
  holdings: [] as PositionHoldingItem[],
  loading: true,
  error: null as string | null,
  lastUpdated: null as number | null,
}

// ============================================================
// 工具函数
// ============================================================

/**
 * 从订单列表汇总持仓数据
 * @remarks 按 symbol 分组，分别累加买入/卖出金额，计算净持仓
 */
function aggregateOrders(orders: Order[]): {
  totalValue: number
  availableFunds: number
  positionRatio: number
  holdings: PositionHoldingItem[]
} {
  const bySymbol = new Map<string, { buys: number; sells: number; totalValue: number }>()
  for (const order of orders) {
    const existing = bySymbol.get(order.symbol) ?? { buys: 0, sells: 0, totalValue: 0 }
    if (order.direction === 'buy') {
      existing.buys += order.amount
    } else {
      existing.sells += order.amount
    }
    existing.totalValue = existing.buys - existing.sells
    bySymbol.set(order.symbol, existing)
  }

  const holdings: PositionHoldingItem[] = Array.from(bySymbol.entries())
    .filter(([, val]) => val.totalValue > 0)
    .map(([symbol, val], i) => ({
      symbol,
      name: symbol,
      value: val.totalValue,
      ratio: 0,
      color: PIE_COLORS[i % PIE_COLORS.length]!,
      direction: 'buy' as const,
    }))

  const totalValue = holdings.reduce((sum, h) => sum + h.value, 0)
  for (const h of holdings) {
    h.ratio = totalValue > 0 ? Math.round((h.value / totalValue) * 1000) / 10 : 0
  }

  // 可用资金（占位估算：假设总资产为持仓的 1.5 倍）
  const estimatedTotal = totalValue * 1.5
  const availableFunds = estimatedTotal - totalValue
  const positionRatio = estimatedTotal > 0
    ? Math.round((totalValue / estimatedTotal) * 1000) / 10
    : 0

  return { totalValue, availableFunds, positionRatio, holdings }
}

// ============================================================
// Store
// ============================================================

export const usePositionStore = create<PositionState>((set) => ({
  ...initialState,

  refresh: async () => {
    logger.info('[positionStore] refresh 开始')
    set({ loading: true, error: null })

    try {
      // P1-E Store 拆分修复：通过 services/trading/tradingService 读取订单，
      // 不再直接订阅 orderStore 内存状态，解除 Store-to-Store 耦合。
      const result = await getOrders()
      if (!result.success) {
        throw new Error(result.error ?? '获取订单失败')
      }
      const orders = result.data ?? []
      const aggregated = aggregateOrders(orders)
      set({
        ...aggregated,
        loading: false,
        lastUpdated: Date.now(),
      })
      logger.info('[positionStore] refresh 完成', {
        holdings: aggregated.holdings.length,
        totalValue: aggregated.totalValue,
      })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[positionStore] refresh 失败', { error: message })
      set({ error: message, loading: false })
    }
  },

  recomputeFromOrders: (orders) => {
    const result = aggregateOrders(orders)
    set({
      ...result,
      lastUpdated: Date.now(),
    })
    logger.info('[positionStore] 从 OrderStore 派生持仓完成', {
      holdings: result.holdings.length,
      totalValue: result.totalValue,
    })
    withBroadcast(EVENT_NAMES.HOLDINGS_CHANGED, { action: 'recompute', holdings: result.holdings.length })
  },

  setLoading: (loading) => set({ loading }),

  setError: (error) => set({ error }),

  reset: () => {
    logger.info('[positionStore] reset')
    set({ ...initialState })
    withBroadcast(EVENT_NAMES.HOLDINGS_CHANGED, { action: 'reset' })
  },
}))

// OrderStore 订阅生命周期
// ============================================================
// P1-E Store 拆分修复：不再直接订阅 useOrderStore 的 Zustand 状态，
// 改为订阅 EventBus 的 ORDERS_CHANGED 事件，实现 Store 间解耦。
// 由组件层 useEffect 调用 init，返回的 cleanup 函数中取消订阅。

let _unsubscribeOrders: (() => void) | null = null
let _debounceTimer: ReturnType<typeof setTimeout> | null = null
let _isRefreshing = false

/** 去抖合并窗口（毫秒）：高频订单变化合并为一次重算 */
const DEBOUNCE_MS = 200

/** 初始化订单变更事件订阅，当 orders 变化时自动重新派生持仓 */
export function initPositionStoreSubscriptions(): () => void {
  if (_unsubscribeOrders) {
    logger.warn('[positionStore] Subscriptions already initialized, skipping')
    return _unsubscribeOrders
  }

  const handleOrdersChanged = () => {
    logger.info('[positionStore] ORDERS_CHANGED event received, scheduling debounced recompute')
    if (_debounceTimer) {
      clearTimeout(_debounceTimer)
    }
    _debounceTimer = setTimeout(() => {
      _debounceTimer = null
      if (_isRefreshing) {
        logger.debug('[positionStore] recomputeFromOrders skipped: isRefreshing is true')
        return
      }
      _isRefreshing = true
      void usePositionStore.getState().refresh().finally(() => {
        _isRefreshing = false
      })
    }, DEBOUNCE_MS)
  }

  _unsubscribeOrders = eventBus.on(EVENT_NAMES.ORDERS_CHANGED, handleOrdersChanged)

  logger.info('[positionStore] ORDERS_CHANGED event subscription initialized (debounce=200ms)')

  return () => {
    if (_debounceTimer) {
      clearTimeout(_debounceTimer)
      _debounceTimer = null
    }
    _unsubscribeOrders?.()
    _unsubscribeOrders = null
    _isRefreshing = false
    logger.info('[positionStore] ORDERS_CHANGED event subscription destroyed')
  }
}

/**
 * @module riskStore
 * @lifecycle @Global
 * @description 风控网关状态管理。管理风控三态（正常/警告/阻塞）、裁决记录、
 * 回路状态（circuit breaker），提供 checkOrderRisk 调用入口及 DataBridge 订阅。
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { checkOrderRisk, type OrderRiskInput, type RiskCheckResult } from '@/services/trading/riskEngine'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION, MODULE_ID, type EnvelopeAction } from '@/config/dbConfig'
import type { SignalDirection } from '@/config/tradingConfig'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

/** 风控三态 */
export type RiskTriState = 'normal' | 'warning' | 'blocked'

/** 裁决记录 */
export interface RiskVerdict {
  id: string
  timestamp: number
  symbol: string
  direction: SignalDirection
  input: OrderRiskInput
  result: RiskCheckResult
  triState: RiskTriState
}

/** 回路状态 */
export type CircuitState = 'closed' | 'open' | 'half-open'

// ============================================================
// Store 接口
// ============================================================

interface RiskState {
  /** 当前风控三态 */
  triState: RiskTriState
  /** 回路状态 */
  circuitState: CircuitState
  /** 最近裁决记录（最多保留 50 条） */
  verdicts: RiskVerdict[]
  /** 加载状态 */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 最后检查时间戳 */
  lastChecked: number

  // Actions
  /** 执行风控检查 */
  checkRisk: (input: OrderRiskInput) => Promise<RiskCheckResult>
  /** 设置回路状态 */
  setCircuitState: (state: CircuitState) => void
  /** 清空裁决记录 */
  clearVerdicts: () => void
}

// ============================================================
// 常量
// ============================================================

const MAX_VERDICTS = 50

// ============================================================
// 辅助函数
// ============================================================

function deriveTriState(result: RiskCheckResult): RiskTriState {
  if (!result.ok || result.blocks.length > 0) return 'blocked'
  if (result.warnings.length > 0) return 'warning'
  return 'normal'
}

function generateVerdictId(): string {
  return `verdict-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

// ============================================================
// Store
// ============================================================

export const useRiskStore = create<RiskState>((set, get) => ({
  triState: 'normal',
  circuitState: 'closed',
  verdicts: [],
  loading: false,
  error: null,
  lastChecked: 0,

  checkRisk: async (input: OrderRiskInput) => {
    logger.info('[riskStore] checkRisk 开始', { symbol: input.symbol, direction: input.direction })
    set({ loading: true, error: null })

    try {
      const result = await checkOrderRisk(input)
      const triState = deriveTriState(result)

      const verdict: RiskVerdict = {
        id: generateVerdictId(),
        timestamp: Date.now(),
        symbol: input.symbol,
        direction: input.direction,
        input,
        result,
        triState,
      }

      // 追加裁决记录，超出上限则淘汰最早的
      const prevVerdicts = get().verdicts
      const nextVerdicts = [verdict, ...prevVerdicts].slice(0, MAX_VERDICTS)

      // 若为 blocked 状态，自动触发回路开路
      let nextCircuitState = get().circuitState
      if (triState === 'blocked' && nextCircuitState === 'closed') {
        nextCircuitState = 'open'
        logger.warn('[riskStore] 风控阻塞，回路状态切换为 open')
      }

      set({
        triState,
        verdicts: nextVerdicts,
        loading: false,
        lastChecked: verdict.timestamp,
        circuitState: nextCircuitState,
      })

      logger.info('[riskStore] checkRisk 完成', {
        symbol: input.symbol,
        triState,
        blocks: result.blocks.length,
        warnings: result.warnings.length,
      })

      return result
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[riskStore] checkRisk 失败: ${message}`)
      set({ loading: false, error: message })
      return { ok: false, warnings: [], blocks: [message] }
    }
  },

  setCircuitState: (state: CircuitState) => {
    logger.info('[riskStore] setCircuitState', { state })
    set({ circuitState: state })
    withBroadcast(EVENT_NAMES.RISK_CHANGED, { action: 'setCircuitState', state })
  },

  clearVerdicts: () => {
    logger.info('[riskStore] clearVerdicts')
    set({ verdicts: [] })
    withBroadcast(EVENT_NAMES.RISK_CHANGED, { action: 'clearVerdicts' })
  },
}))

// ============================================================
// 派生查询
// ============================================================

/** 获取最近 N 条裁决记录 */
export function recentVerdicts(limit: number = 10): RiskVerdict[] {
  return useRiskStore.getState().verdicts.slice(0, limit)
}

/** 获取指定 symbol 的裁决记录 */
export function verdictsBySymbol(symbol: string): RiskVerdict[] {
  return useRiskStore.getState().verdicts.filter((v) => v.symbol === symbol)
}

// ============================================================
// DataBridge 订阅
// ============================================================

let _unsubscribeOrders: (() => void) | null = null

const RISK_RELEVANT_ACTIONS = new Set<EnvelopeAction>([
  ENVELOPE_ACTION.insertOrder,
  ENVELOPE_ACTION.updateOrder,
])

/** 初始化 DataBridge 订阅，返回 cleanup 函数 */
export function initRiskStoreSubscriptions(): () => void {
  if (_unsubscribeOrders) {
    logger.warn('[riskStore] Subscriptions already initialized')
    return () => destroyRiskStoreSubscriptions()
  }

  _unsubscribeOrders = dataBridge.subscribe(
    'orders',
    (envelope) => {
      if (envelope.meta.source === MODULE_ID.trading || envelope.meta.source === MODULE_ID.tradinghub) {
        return
      }
      if (RISK_RELEVANT_ACTIONS.has(envelope.meta.action)) {
        logger.info('[riskStore] DataBridge event on orders channel', {
          action: envelope.meta.action,
          traceId: envelope.meta.traceId,
        })
        // 订单变更时，可考虑重新评估当前风控状态
      }
    },
  )

  logger.info('[riskStore] DataBridge subscriptions initialized')
  return () => destroyRiskStoreSubscriptions()
}

function destroyRiskStoreSubscriptions(): void {
  _unsubscribeOrders?.()
  _unsubscribeOrders = null
  logger.info('[riskStore] DataBridge subscriptions destroyed')
}

/**
 * @module rotationSignalStore
 * @lifecycle @Global
 * @description 轮动信号检测状态管理。管理板块轮动信号列表，
 * 提供信号检测、单板块检测等操作，以及 triggeredSignals/bySector 等派生查询。
 *
 * @compliance
 * - 所有数据展示来自 rotationSignalDetector 服务，禁止硬编码
 * - 核心分支包含 logger.info 打印
 * - 遵循现有 Zustand Store 风格
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { detect, type RotationSignalInput, type RotationSignal } from '@/services/scoring/rotationSignalDetector'

const logger = getLogger()

// ============================================================
// 内部样本数据（后续由 dataLayer 替代）
// ============================================================

const DEFAULT_SAMPLES: RotationSignalInput[] = [
  {
    sectorId: '银行',
    volume: { history: [...Array(50).fill(60000), 100000, 110000, 120000, 115000, 105000] },
    capitalFlow: { dailyNetFlow: [10, 20, 15, 30, 25] },
    goldenCross: { closes: [...Array(20).fill(105), 100, 100, 100, 100, 130] },
  },
  {
    sectorId: '钢铁',
    volume: { history: [...Array(50).fill(30000), 35000, 32000, 31000, 33000, 34000] },
    capitalFlow: { dailyNetFlow: [5, 3, -2, 8, 2] },
    goldenCross: { closes: [...Array(25).fill(100)] },
  },
  {
    sectorId: '煤炭',
    volume: { history: [...Array(40).fill(15000), ...Array(10).fill(20000), 16000, 16000, 16000, 16000, 16000] },
    capitalFlow: { dailyNetFlow: [-3, -5, -2, 1, -1] },
    goldenCross: { closes: Array(25).fill(100).map((v, i) => v - i * 0.5) },
  },
]

// ============================================================
// Store 接口
// ============================================================

interface RotationSignalState {
  /** 信号列表 */
  signals: RotationSignal[]
  /** 加载状态 */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 最后更新时间戳 */
  lastUpdated: number

  // Actions
  fetchSignals: (inputs?: RotationSignalInput[]) => void
  detectSignal: (sectorId: string, inputs?: RotationSignalInput[]) => void
  clearSignals: () => void
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  signals: [] as RotationSignal[],
  loading: false,
  error: null as string | null,
  lastUpdated: 0,
}

// ============================================================
// Store
// ============================================================

export const useRotationSignalStore = create<RotationSignalState>((set) => ({
  ...initialState,

  fetchSignals: (inputs) => {
    logger.info('[rotationSignalStore] fetchSignals 开始')
    set({ loading: true, error: null })

    try {
      const sourceInputs = inputs ?? DEFAULT_SAMPLES
      const results = sourceInputs.map((input) => {
        const signal = detect(input)
        logger.info(
          `[rotationSignalStore] ${input.sectorId} 检测: triggered=${signal.triggered} strength=${signal.strength}`,
        )
        return signal
      })

      set({
        signals: results,
        loading: false,
        lastUpdated: Date.now(),
      })
      logger.info(`[rotationSignalStore] fetchSignals 完成: ${results.length} 个板块`)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[rotationSignalStore] fetchSignals 失败: ${message}`)
      set({ error: message, loading: false })
    }
  },

  detectSignal: (sectorId, inputs) => {
    logger.info(`[rotationSignalStore] detectSignal: ${sectorId}`)
    const sourceInputs = inputs ?? DEFAULT_SAMPLES
    const target = sourceInputs.find((i) => i.sectorId === sectorId)

    if (!target) {
      logger.warn(`[rotationSignalStore] detectSignal 未找到板块: ${sectorId}`)
      return
    }

    try {
      const newSignal = detect(target)
      set((state) => {
        const signals = state.signals.map((s) =>
          s.sectorId === sectorId ? newSignal : s,
        )
        return { signals, lastUpdated: Date.now() }
      })
      logger.info(
        `[rotationSignalStore] detectSignal 完成: ${sectorId} triggered=${newSignal.triggered} strength=${newSignal.strength}`,
      )
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[rotationSignalStore] detectSignal 失败: ${message}`)
      set({ error: message })
    }
  },

  clearSignals: () => {
    logger.info('[rotationSignalStore] clearSignals')
    set({ ...initialState })
  },
}))

// ============================================================
// 派生查询（Getters）
// ============================================================

/** 获取已触发的信号列表 */
export function triggeredSignals(): RotationSignal[] {
  const { signals } = useRotationSignalStore.getState()
  return signals.filter((s) => s.triggered)
}

/** 按板块查询 */
export function bySector(sectorId: string): RotationSignal | undefined {
  const { signals } = useRotationSignalStore.getState()
  return signals.find((s) => s.sectorId === sectorId)
}

/**
 * @module scoreDocStore
 * @lifecycle @Global
 * @description 评分文档版本库页面状态管理。管理股票代码选择、股票列表、
 * 评分文档版本列表，提供加载、刷新、清空、导出等操作。
 *
 * @see @/pages/analysis/ScoreDocPage.tsx - 消费此 Store 的评分文档页面
 *
 * @compliance
 * - 所有数据请求经 Store Action 分发
 * - 核心分支包含 logger.info 打印
 * - 遵循现有 Zustand Store 风格
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import type { ScoreDocVersion, Stock } from '@/data/types'
import { buildReportMarkdown, getRecentVersions, exportSymbolMd, listScoreDocsBySymbol, buildScoreDocDiff, type ScoreDocDiff } from '@/services/analysis/scoreDocService'
import { listStocks } from '@/services/stockpool/stockpoolService'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION } from '@/config/dbConfig'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import { dataLayer } from '@/data/dataLayer'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

export interface ScoreDocState {
  /** 当前选中的股票代码 */
  symbol: string
  /** 股票列表（用于下拉选择） */
  stocks: Stock[]
  /** 评分文档版本列表 */
  versions: ScoreDocVersion[]
  /** 加载状态 */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 历史文档列表（供 ScoreHistoryPanel 使用） */
  historyDocs: ScoreDocVersion[]
  /** 历史文档差异（最新版本 vs 上一版本） */
  historyDiff: ScoreDocDiff | null
  /** 历史文档加载状态 */
  historyLoading: boolean
  /** 历史文档错误信息 */
  historyError: string | null

  // Actions
  /** 设置当前股票代码 */
  setSymbol: (symbol: string) => void
  /** 加载股票列表 */
  loadStocks: () => Promise<void>
  /** 加载当前股票的评分文档版本 */
  loadVersions: () => Promise<void>
  /** 刷新当前股票的评分文档版本 */
  refresh: () => Promise<void>
  /** 清空当前选择及结果（保留股票列表） */
  clear: () => void
  /** 导出当前股票全部 Markdown */
  exportAll: () => Promise<void>
  /** 加载股票代码列表（供下拉选择，封装 dataLayer.stocks.list） */
  loadStockSymbols: () => Promise<string[]>
  /** 生成研究报告 Markdown（封装 buildReportMarkdown + getRecentVersions） */
  generateReport: (symbol: string) => Promise<{ symbol: string; version: number; markdown: string; generatedAt: string }>
  /** 加载历史文档列表并计算差异（供 ScoreHistoryPanel 使用） */
  loadHistoryDocs: (symbol: string) => Promise<void>
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  symbol: '',
  stocks: [] as Stock[],
  versions: [] as ScoreDocVersion[],
  loading: false,
  error: null as string | null,
  historyDocs: [] as ScoreDocVersion[],
  historyDiff: null as ScoreDocDiff | null,
  historyLoading: false,
  historyError: null as string | null,
}

// ============================================================
// Store
// ============================================================

export const useScoreDocStore = create<ScoreDocState>((set, get) => ({
  ...initialState,

  setSymbol: (symbol: string) => {
    logger.info(`[scoreDocStore] setSymbol: ${symbol}`)
    set({ symbol })
  },

  loadStocks: async () => {
    logger.info('[scoreDocStore] loadStocks 开始')
    set({ loading: true, error: null })

    try {
      const result = await listStocks()
      if (result.success && result.data) {
        set({ stocks: result.data, loading: false })
        logger.info(`[scoreDocStore] loadStocks 完成: ${result.data.length} 只股票`)
      } else {
        const message = result.error ?? '加载股票列表失败'
        logger.error(`[scoreDocStore] loadStocks 失败: ${message}`)
        set({ error: message, loading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadStocks 异常: ${message}`)
      set({ error: `加载失败：${message}`, loading: false })
    }
  },

  loadVersions: async () => {
    const { symbol } = get()
    if (!symbol) {
      logger.info('[scoreDocStore] loadVersions 跳过: symbol 为空')
      set({ versions: [], error: null })
      return
    }

    logger.info(`[scoreDocStore] loadVersions 开始: ${symbol}`)
    set({ loading: true, error: null })

    try {
      const result = await getRecentVersions(symbol)
      if (result.success && result.data) {
        set({ versions: result.data, loading: false })
        logger.info(`[scoreDocStore] loadVersions 完成: ${symbol}, ${result.data.length} 个版本`)
      } else {
        const message = result.error ?? '加载评分文档版本失败'
        logger.error(`[scoreDocStore] loadVersions 失败: ${symbol}, ${message}`)
        set({ error: message, loading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadVersions 异常: ${symbol}, ${message}`)
      set({ error: `加载失败：${message}`, loading: false })
    }
  },

  refresh: async () => {
    const { symbol } = get()
    if (!symbol) {
      logger.info('[scoreDocStore] refresh 跳过: symbol 为空')
      return
    }

    logger.info(`[scoreDocStore] refresh 开始: ${symbol}`)
    set({ loading: true, error: null })

    try {
      const result = await getRecentVersions(symbol)
      if (result.success && result.data) {
        set({ versions: result.data, loading: false })
        logger.info(`[scoreDocStore] refresh 完成: ${symbol}, ${result.data.length} 个版本`)
      } else {
        const message = result.error ?? '加载评分文档版本失败'
        logger.error(`[scoreDocStore] refresh 失败: ${symbol}, ${message}`)
        set({ error: message, loading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] refresh 异常: ${symbol}, ${message}`)
      set({ error: `加载失败：${message}`, loading: false })
    }
  },

  clear: () => {
    logger.info('[scoreDocStore] clear')
    set({ symbol: '', versions: [], error: null, loading: false })
    withBroadcast(EVENT_NAMES.SCORE_DOCS_CHANGED, { action: 'clear' })
  },

  exportAll: async () => {
    const { symbol, versions } = get()
    if (!symbol || versions.length === 0) {
      logger.warn('[scoreDocStore] exportAll 跳过: symbol 为空或版本列表为空')
      return
    }

    logger.info(`[scoreDocStore] exportAll 开始: ${symbol}`)

    try {
      const result = await exportSymbolMd(symbol)
      if (result.success && result.data) {
        const blob = new Blob([result.data], { type: 'text/markdown;charset=utf-8' })
        const url = URL.createObjectURL(blob)
        const link = document.createElement('a')
        link.href = url
        link.download = `${symbol}_score_docs.md`
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
        URL.revokeObjectURL(url)
        logger.info(`[scoreDocStore] exportAll 完成: ${symbol}`)
      } else {
        const message = result.error ?? '导出失败'
        logger.error(`[scoreDocStore] exportAll 失败: ${symbol}, ${message}`)
        set({ error: message })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] exportAll 异常: ${symbol}, ${message}`)
      set({ error: `导出失败：${message}` })
    }
  },

  loadHistoryDocs: async (symbol) => {
    if (!symbol) {
      logger.info('[scoreDocStore] loadHistoryDocs 跳过: symbol 为空')
      set({ historyDocs: [], historyDiff: null, historyError: null, historyLoading: false })
      return
    }

    logger.info(`[scoreDocStore] loadHistoryDocs 开始: ${symbol}`)
    set({ historyLoading: true, historyError: null })

    try {
      const result = await listScoreDocsBySymbol(symbol)
      if (result.success) {
        const list = result.data ?? []
        let diff: ScoreDocDiff | null = null
        if (list.length >= 2) {
          const latest = list[0]!
          const previous = list[1]!
          diff = buildScoreDocDiff(latest, previous)
        }
        set({ historyDocs: list, historyDiff: diff, historyLoading: false })
        logger.info(`[scoreDocStore] loadHistoryDocs 完成: ${symbol}, ${list.length} 个版本`)
      } else {
        const message = result.error ?? '加载失败'
        logger.error(`[scoreDocStore] loadHistoryDocs 失败: ${symbol}, ${message}`)
        set({ historyError: message, historyLoading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadHistoryDocs 异常: ${symbol}, ${message}`)
      set({ historyError: `加载失败：${message}`, historyLoading: false })
    }
  },

  loadStockSymbols: async () => {
    logger.info('[scoreDocStore] loadStockSymbols 开始')
    try {
      const stocks = await dataLayer.stocks.list()
      const uniqueSymbols = Array.from(new Set(stocks.map(s => s.symbol))).sort()
      logger.info(`[scoreDocStore] loadStockSymbols 完成: ${uniqueSymbols.length} 个代码`)
      return uniqueSymbols
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadStockSymbols 异常: ${message}`)
      throw err
    }
  },

  generateReport: async (symbol) => {
    logger.info(`[scoreDocStore] generateReport 开始: ${symbol}`)
    try {
      const recentVersionsResult = await getRecentVersions(symbol, 1)
      if (!recentVersionsResult.success || !recentVersionsResult.data || recentVersionsResult.data.length === 0) {
        throw new Error(`股票 ${symbol} 暂无评分文档，请先生成评分`)
      }
      const latestVersion = recentVersionsResult.data[0]!
      const markdown = buildReportMarkdown(latestVersion)
      const report = {
        symbol,
        version: latestVersion.version,
        markdown,
        generatedAt: new Date().toISOString(),
      }
      logger.info(`[scoreDocStore] generateReport 完成: ${symbol} V${latestVersion.version}`)
      return report
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] generateReport 异常: ${symbol}, ${message}`)
      throw err
    }
  },
}))

// ============================================================
// DataBridge 订阅（用于跨模块数据同步）
// ============================================================

let _unsubscribeScoreDocs: (() => void) | undefined

export function initScoreDocStoreSubscriptions(): () => void {
  destroyScoreDocStoreSubscriptions()
  logger.info('[scoreDocStore] 初始化 DataBridge score_docs 频道订阅')

  _unsubscribeScoreDocs = dataBridge.subscribe(
    'score_docs',
    (envelope) => {
      if (envelope.meta.action === ENVELOPE_ACTION.saveScoreDocs) {
        logger.info('[scoreDocStore] DataBridge event received: saveScoreDocs', {
          traceId: envelope.meta.traceId,
        })
      }
    },
  )

  return () => destroyScoreDocStoreSubscriptions()
}

export function destroyScoreDocStoreSubscriptions(): void {
  if (_unsubscribeScoreDocs) {
    _unsubscribeScoreDocs()
    _unsubscribeScoreDocs = undefined
  }
}

/**
 * @module sevenDimConfigStore
 * @description 七维采集配置 Store（Zustand）。
 *
 * 职责：
 * - 管理 8 个采集维度的启用/频率/数据源等配置
 * - 管理当前选中的策略模板
 * - 管理全局参数（标的数、限流等）
 * - 提供配置序列化/反序列化能力
 * - 提供 isClickable / isVisible 等页面守卫状态
 *
 * @see V6 Pro: cockpit-app/src/data/collectConfig.ts (createPresetConfig)
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import {
  type DimensionConfig,
  type StrategyTemplateId,
  type UpdateFrequency,
  type DataSourceType,
  type StrategyTemplate,
  DEFAULT_DIMENSIONS,
  STRATEGY_TEMPLATES,
  GLOBAL_LIMITS,
  estimateTotalMonthlyCalls,
} from '@/config/collectConfig'

const logger = getLogger()

// ============================================================
// Store 接口定义
// ============================================================

export interface SevenDimConfigState {
  // --- 状态 ---
  /** 当前选中的策略模板 */
  activeTemplate: StrategyTemplateId
  /** 8个维度配置 */
  dimensions: DimensionConfig[]
  /** 目标标的数 */
  symbolCount: number
  /** 历史数据天数 */
  historyDays: number
  /** 是否有未保存的修改 */
  isDirty: boolean
  /** 是否正在保存 */
  isSaving: boolean
  /** 是否正在执行采集 */
  isCollecting: boolean
  /** 采集进度（0-100） */
  collectProgress: number
  /** 错误信息 */
  error: string | null

  // --- 派生计算 ---
  /** 已启用的维度数 */
  enabledCount: () => number
  /** 月调用总量预估 */
  monthlyCallEstimate: () => number
  /** 是否可交互（页面守卫） */
  isClickable: () => boolean
  /** 不可交互时的提示文本 */
  tooltipText: () => string

  // --- Actions ---
  /** 应用策略模板 */
  applyTemplate: (templateId: StrategyTemplateId) => void
  /** 切换维度启用状态 */
  toggleDimension: (code: string) => void
  /** 设置维度频率 */
  setDimensionFrequency: (code: string, frequency: UpdateFrequency) => void
  /** 设置维度数据源 */
  setDimensionSources: (code: string, sources: DataSourceType[]) => void
  /** 设置目标标的数 */
  setSymbolCount: (count: number) => void
  /** 设置历史天数 */
  setHistoryDays: (days: number) => void
  /** 重置为默认配置 */
  reset: () => void
  /** 保存配置 */
  saveConfig: () => Promise<void>
  /** 执行采集 */
  runCollection: () => Promise<void>
  /** 清除错误 */
  clearError: () => void
}

// ============================================================
// 辅助函数
// ============================================================

/**
 * 根据策略模板生成维度配置
 */
function generateDimensionsFromTemplate(template: StrategyTemplate): DimensionConfig[] {
  return DEFAULT_DIMENSIONS.map((dim) => ({
    ...dim,
    enabled: template.dimensions.includes(dim.code),
    frequency: dim.enabled ? template.updateInterval : dim.frequency,
  }))
}

// ============================================================
// Store 实现
// ============================================================

export const useSevenDimConfigStore = create<SevenDimConfigState>((set, get) => ({
  // --- 初始状态 ---
  activeTemplate: 'value',
  dimensions: generateDimensionsFromTemplate(STRATEGY_TEMPLATES[0]!),
  symbolCount: 40,
  historyDays: 252,
  isDirty: false,
  isSaving: false,
  isCollecting: false,
  collectProgress: 0,
  error: null,

  // --- 派生计算 ---
  enabledCount: () => get().dimensions.filter((d) => d.enabled).length,

  monthlyCallEstimate: () =>
    estimateTotalMonthlyCalls(get().dimensions, get().symbolCount),

  isClickable: () => {
    const state = get()
    return !state.isSaving && !state.isCollecting
  },

  tooltipText: () => {
    const state = get()
    if (state.isSaving) return '配置保存中，请稍候...'
    if (state.isCollecting) return '采集进行中，请稍候...'
    return ''
  },

  // --- Actions ---
  applyTemplate: (templateId) => {
    const template = STRATEGY_TEMPLATES.find((t) => t.id === templateId)
    if (!template) {
      logger.warn(`[SevenDimConfigStore] 未找到策略模板: ${templateId}`)
      return
    }

    logger.info(`[SevenDimConfigStore] 应用策略模板: ${template.name}`, {
      dimensions: template.dimensions,
      frequency: template.updateInterval,
    })

    set({
      activeTemplate: templateId,
      dimensions: generateDimensionsFromTemplate(template),
      historyDays: template.historyDays,
      isDirty: true,
    })
  },

  toggleDimension: (code) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code ? { ...dim, enabled: !dim.enabled } : dim,
      ),
      isDirty: true,
    }))

    const dim = get().dimensions.find((d) => d.code === code)
    logger.info(`[SevenDimConfigStore] 维度切换: ${code} → ${dim?.enabled ? '启用' : '禁用'}`)
  },

  setDimensionFrequency: (code, frequency) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code ? { ...dim, frequency } : dim,
      ),
      isDirty: true,
    }))

    logger.info(`[SevenDimConfigStore] 维度频率更新: ${code} → ${frequency}`)
  },

  setDimensionSources: (code, sources) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code ? { ...dim, sources } : dim,
      ),
      isDirty: true,
    }))

    logger.info(`[SevenDimConfigStore] 维度数据源更新: ${code} → ${sources.join(', ')}`)
  },

  setSymbolCount: (count) => {
    const clamped = Math.max(1, Math.min(count, GLOBAL_LIMITS.maxSymbols))
    set({ symbolCount: clamped, isDirty: true })
    logger.info(`[SevenDimConfigStore] 标的数设置: ${clamped}`)
  },

  setHistoryDays: (days) => {
    const clamped = Math.max(1, Math.min(days, 1000))
    set({ historyDays: clamped, isDirty: true })
  },

  reset: () => {
    logger.info('[SevenDimConfigStore] 重置为默认配置')
    set({
      activeTemplate: 'value',
      dimensions: generateDimensionsFromTemplate(STRATEGY_TEMPLATES[0]!),
      symbolCount: 40,
      historyDays: 252,
      isDirty: false,
      isSaving: false,
      isCollecting: false,
      collectProgress: 0,
      error: null,
    })
  },

  saveConfig: async () => {
    const state = get()
    if (state.isSaving) return

    set({ isSaving: true, error: null })

    try {
      logger.info('[SevenDimConfigStore] 保存采集配置', {
        template: state.activeTemplate,
        enabledCount: state.enabledCount(),
        symbolCount: state.symbolCount,
      })

      // TODO: 调用 DataBridge.forward() 持久化配置到 IndexedDB
      // await dataBridge.forward('collectConfig.save', { dimensions, symbolCount })

      await new Promise((resolve) => setTimeout(resolve, 300))

      set({ isSaving: false, isDirty: false })
      logger.info('[SevenDimConfigStore] 配置保存成功')
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[SevenDimConfigStore] 配置保存失败', { error: message })
      set({ isSaving: false, error: message })
    }
  },

  runCollection: async () => {
    const state = get()
    if (state.isCollecting) return

    set({ isCollecting: true, collectProgress: 0, error: null })

    try {
      const enabledDims = state.dimensions.filter((d) => d.enabled)
      logger.info('[SevenDimConfigStore] 开始采集', {
        dimensions: enabledDims.map((d) => d.code).join(', '),
        symbolCount: state.symbolCount,
      })

      // TODO: 调用 fetcherService 执行实际采集
      // 模拟进度更新
      for (let i = 0; i <= 100; i += 10) {
        set({ collectProgress: i })
        await new Promise((resolve) => setTimeout(resolve, 100))
      }

      set({ isCollecting: false, collectProgress: 100 })
      logger.info('[SevenDimConfigStore] 采集完成')
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[SevenDimConfigStore] 采集失败', { error: message })
      set({ isCollecting: false, error: message })
    }
  },

  clearError: () => set({ error: null }),
}))

/**
 * @module signalQualityStore
 * @lifecycle @Global
 * @description 信号质量复盘状态管理。管理信号准确率、择时得分、最大回撤、Sharpe 等
 * 绩效指标，提供复盘数据加载和 DataBridge 订阅。
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { dataLayer } from '@/data/dataLayer'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION, MODULE_ID, type EnvelopeAction } from '@/config/dbConfig'
import type { Signal } from '@/data/types'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

/** 信号质量指标 */
export interface SignalQualityMetrics {
  /** 信号总数 */
  totalSignals: number
  /** 已实现信号数（有后续价格数据） */
  realizedSignals: number
  /** 准确率（0-1）：信号方向与实际走势一致的比例 */
  accuracy: number
  /** 择时得分（0-100）：基于信号发出时机与实际拐点的时间差 */
  timingScore: number
  /** 最大回撤（0-1，负值表示亏损） */
  maxDrawdown: number
  /** Sharpe 比率 */
  sharpeRatio: number
  /** 平均持仓天数 */
  avgHoldingDays: number
  /** 胜率（0-1） */
  winRate: number
  /** 盈亏比 */
  profitLossRatio: number
}

/** 单个信号的复盘记录 */
export interface SignalReviewRecord {
  signalId: string
  symbol: string
  direction: 'buy' | 'sell' | 'hold' | 'watch'
  type: string
  confidence: number
  issuedAt: number
  /** 信号发出后 N 日的实际走势 */
  actualReturn?: number
  /** 信号是否正确 */
  correct?: boolean
  /** 持仓天数 */
  holdingDays?: number
  /** 盈亏百分比 */
  pnlPercent?: number
}

// ============================================================
// Store 接口
// ============================================================

interface SignalQualityState {
  /** 质量指标 */
  metrics: SignalQualityMetrics | null
  /** 复盘记录列表 */
  reviews: SignalReviewRecord[]
  /** 加载状态 */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 最后更新时间戳 */
  lastUpdated: number

  // Actions
  /** 加载复盘数据 */
  loadReviews: () => Promise<void>
  /** 重新计算质量指标 */
  recalculateMetrics: () => void
}

// ============================================================
// 辅助函数
// ============================================================

function calculateMetrics(reviews: SignalReviewRecord[]): SignalQualityMetrics {
  const totalSignals = reviews.length
  const realizedReviews = reviews.filter((r) => r.actualReturn !== undefined)
  const realizedSignals = realizedReviews.length

  if (realizedSignals === 0) {
    return {
      totalSignals,
      realizedSignals: 0,
      accuracy: 0,
      timingScore: 0,
      maxDrawdown: 0,
      sharpeRatio: 0,
      avgHoldingDays: 0,
      winRate: 0,
      profitLossRatio: 0,
    }
  }

  // 准确率
  const correctCount = realizedReviews.filter((r) => r.correct).length
  const accuracy = correctCount / realizedSignals

  // 过滤 pnlPercent 非空的记录，用于胜率/盈亏比/回撤/Sharpe 计算
  const pnlReviews = realizedReviews.filter((r) => r.pnlPercent != null)
  const pnlMissingCount = realizedSignals - pnlReviews.length
  if (pnlMissingCount > 0) {
    logger.warn('[SignalQuality] pnlPercent 缺失', { missingCount: pnlMissingCount, totalCount: realizedSignals })
  }

  // 胜率（基于有 pnlPercent 的记录）
  const pnlBase = pnlReviews.length > 0 ? pnlReviews : realizedReviews
  const winningTrades = pnlBase.filter((r) => (r.pnlPercent as number) > 0).length
  const winRate = winningTrades / pnlBase.length

  // 盈亏比
  const avgWin =
    pnlBase.filter((r) => (r.pnlPercent as number) > 0).reduce((sum, r) => sum + (r.pnlPercent as number), 0) /
    Math.max(winningTrades, 1)
  const losingTrades = pnlBase.filter((r) => (r.pnlPercent as number) < 0)
  const avgLoss =
    Math.abs(
      losingTrades.reduce((sum, r) => sum + (r.pnlPercent as number), 0) /
        Math.max(pnlBase.length - winningTrades, 1),
    )
  const profitLossRatio = avgLoss > 0 ? avgWin / avgLoss : 0

  // 平均持仓天数（过滤 null 值）
  const holdingDaysReviews = realizedReviews.filter((r) => r.holdingDays != null)
  const holdingDaysMissing = realizedSignals - holdingDaysReviews.length
  if (holdingDaysMissing > 0) {
    logger.warn('[SignalQuality] holdingDays 缺失', { missingCount: holdingDaysMissing, totalCount: realizedSignals })
  }
  const holdingDaysList = holdingDaysReviews.map((r) => r.holdingDays as number)
  const avgHoldingDays = holdingDaysList.length > 0
    ? holdingDaysList.reduce((sum, d) => sum + d, 0) / holdingDaysList.length
    : 0

  // 最大回撤（简化计算：取最小 pnlPercent）
  const pnlValues = pnlBase.map((r) => r.pnlPercent as number)
  const maxDrawdown = pnlValues.length > 0 ? Math.min(0, ...pnlValues) / 100 : 0

  // Sharpe 比率（简化：假设无风险利率为 0）
  const returns = pnlValues.map((p) => p / 100)
  const avgReturn = returns.length > 0 ? returns.reduce((sum, r) => sum + r, 0) / returns.length : 0
  const stdDev = returns.length > 0
    ? Math.sqrt(returns.reduce((sum, r) => sum + (r - avgReturn) ** 2, 0) / returns.length)
    : 0
  const sharpeRatio = stdDev > 0 ? avgReturn / stdDev : 0

  // 择时得分（简化：基于信号置信度与实际收益的相关性）
  const timingScore = Math.min(100, accuracy * 100 * 0.7 + winRate * 100 * 0.3)

  return {
    totalSignals,
    realizedSignals,
    accuracy,
    timingScore,
    maxDrawdown,
    sharpeRatio,
    avgHoldingDays,
    winRate,
    profitLossRatio,
  }
}

// ============================================================
// Store
// ============================================================

export const useSignalQualityStore = create<SignalQualityState>((set, get) => ({
  metrics: null,
  reviews: [],
  loading: false,
  error: null,
  lastUpdated: 0,

  loadReviews: async () => {
    logger.info('[signalQualityStore] loadReviews 开始')
    set({ loading: true, error: null })

    try {
      // 从 signals 表加载历史信号
      const signals = await dataLayer.signals.list()
      logger.info(`[signalQualityStore] 加载到 ${signals.length} 个信号`)

      // 转换为复盘记录（简化：实际应查询后续价格数据）
      const reviews: SignalReviewRecord[] = signals.map((signal: Signal) => ({
        signalId: signal.id,
        symbol: signal.symbol,
        direction: signal.direction as 'buy' | 'sell' | 'hold' | 'watch',
        type: signal.type,
        confidence: signal.confidence,
        issuedAt: signal.createdAt,
        // 实际应查询信号发出后的价格数据，此处留空
        actualReturn: undefined,
        correct: undefined,
        holdingDays: undefined,
        pnlPercent: undefined,
      }))

      set({
        reviews,
        loading: false,
        lastUpdated: Date.now(),
      })

      // 自动计算指标
      get().recalculateMetrics()

      logger.info(`[signalQualityStore] loadReviews 完成: ${reviews.length} 条记录`)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[signalQualityStore] loadReviews 失败: ${message}`)
      set({ loading: false, error: message })
    }
  },

  recalculateMetrics: () => {
    const { reviews } = get()
    const metrics = calculateMetrics(reviews)
    logger.info('[signalQualityStore] recalculateMetrics 完成', {
      accuracy: metrics.accuracy.toFixed(2),
      winRate: metrics.winRate.toFixed(2),
      sharpeRatio: metrics.sharpeRatio.toFixed(2),
    })
    set({ metrics })
    withBroadcast(EVENT_NAMES.SIGNAL_QUALITY_CHANGED, { action: 'recalculateMetrics' })
  },
}))

// ============================================================
// 派生查询
// ============================================================

/** 获取指定 symbol 的复盘记录 */
export function reviewsBySymbol(symbol: string): SignalReviewRecord[] {
  return useSignalQualityStore.getState().reviews.filter((r) => r.symbol === symbol)
}

/** 获取准确率最高的 Top N 信号类型 */
export function topSignalTypes(limit: number = 5): Array<{ type: string; accuracy: number; count: number }> {
  const { reviews } = useSignalQualityStore.getState()
  const typeMap = new Map<string, { correct: number; total: number }>()

  for (const review of reviews) {
    if (review.correct === undefined) continue
    const entry = typeMap.get(review.type) ?? { correct: 0, total: 0 }
    entry.total++
    if (review.correct) entry.correct++
    typeMap.set(review.type, entry)
  }

  return Array.from(typeMap.entries())
    .map(([type, stats]) => ({
      type,
      accuracy: stats.total > 0 ? stats.correct / stats.total : 0,
      count: stats.total,
    }))
    .sort((a, b) => b.accuracy - a.accuracy)
    .slice(0, limit)
}

// ============================================================
// DataBridge 订阅
// ============================================================

let _unsubscribeSignals: (() => void) | null = null

const QUALITY_RELEVANT_ACTIONS = new Set<EnvelopeAction>([
  ENVELOPE_ACTION.insertSignal,
])

/** 初始化 DataBridge 订阅，返回 cleanup 函数 */
export function initSignalQualityStoreSubscriptions(): () => void {
  if (_unsubscribeSignals) {
    logger.warn('[signalQualityStore] Subscriptions already initialized')
    return () => destroySignalQualityStoreSubscriptions()
  }

  _unsubscribeSignals = dataBridge.subscribe(
    'signals',
    (envelope) => {
      if (envelope.meta.source === MODULE_ID.trading || envelope.meta.source === MODULE_ID.tradinghub) {
        return
      }
      if (QUALITY_RELEVANT_ACTIONS.has(envelope.meta.action)) {
        logger.info('[signalQualityStore] DataBridge event on signals channel', {
          action: envelope.meta.action,
          traceId: envelope.meta.traceId,
        })
        // 信号变更时，重新加载复盘数据
        void useSignalQualityStore.getState().loadReviews()
      }
    },
  )

  logger.info('[signalQualityStore] DataBridge subscriptions initialized')
  return () => destroySignalQualityStoreSubscriptions()
}

function destroySignalQualityStoreSubscriptions(): void {
  _unsubscribeSignals?.()
  _unsubscribeSignals = null
  logger.info('[signalQualityStore] DataBridge subscriptions destroyed')
}

/**
 * @module stockAnalysisStore
 * @description 个股分析页面状态管理层。集中管理单只股票的基础信息、K线数据、V6评分及加载状态。
 *
 * @see @/pages/analysis/StockAnalysisPage.tsx - 消费此 Store 的个股分析页面
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import type { DailyQuotes, Stock, V6Score } from '@/data/types'
import {
  loadDailyQuotesForAnalysis,
  loadStockForAnalysis,
  loadV6ScoreForAnalysis,
} from '@/services/analysis/scorePageService'
import { runV6Score } from '@/services/scoring/v6ScoreService'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION } from '@/config/dbConfig'

const logger = getLogger()

// ============================================================
// Store 接口
// ============================================================

interface StockAnalysisState {
  /** 当前选中的股票代码 */
  selectedSymbol: string | null
  /** 股票基础信息 */
  stock: Stock | null
  /** 日 K 数据 */
  quotes: DailyQuotes | null
  /** V6 评分 */
  v6Score: V6Score | null
  /** 初始加载状态 */
  loading: boolean
  /** 评分刷新加载状态 */
  scoreLoading: boolean
  /** 错误信息 */
  error: string | null

  // Actions
  loadStockAnalysis: (symbol: string, signal?: AbortSignal) => Promise<void>
  refreshScore: (symbol: string) => Promise<void>
  clear: () => void
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  selectedSymbol: null as string | null,
  stock: null as Stock | null,
  quotes: null as DailyQuotes | null,
  v6Score: null as V6Score | null,
  loading: false,
  scoreLoading: false,
  error: null as string | null,
}

// ============================================================
// Store
// ============================================================

export const useStockAnalysisStore = create<StockAnalysisState>((set) => ({
  ...initialState,

  loadStockAnalysis: async (symbol: string, signal?: AbortSignal) => {
    const t0 = Date.now()
    logger.info(`[stockAnalysisStore] loadStockAnalysis 开始: ${symbol}`)
    set({
      ...initialState,
      selectedSymbol: symbol,
      loading: true,
    })

    try {
      logger.info(`[stockAnalysisStore] Promise.all 发起: stock + quotes + score`, { symbol })
      const [stockData, quotesData, scoreData] = await Promise.all([
        loadStockForAnalysis(symbol),
        loadDailyQuotesForAnalysis(symbol),
        loadV6ScoreForAnalysis(symbol),
      ])

      if (signal?.aborted) {
        logger.info(`[stockAnalysisStore] loadStockAnalysis 已取消: ${symbol}`)
        return
      }

      logger.info(`[stockAnalysisStore] Promise.all 返回`, {
        symbol,
        hasStock: stockData != null,
        quotesCount: quotesData ? (quotesData as { dates?: unknown[] }).dates?.length ?? 'N/A' : 0,
        hasScore: scoreData != null,
        elapsedMs: Date.now() - t0,
      })

      set({
        stock: stockData ?? null,
        quotes: quotesData ?? null,
        v6Score: scoreData ?? null,
        loading: false,
        error: null,
      })
      logger.info(`[stockAnalysisStore] loadStockAnalysis 完成: ${symbol}, 耗时 ${Date.now() - t0}ms`)
    } catch (err) {
      if (signal?.aborted) {
        logger.info(`[stockAnalysisStore] loadStockAnalysis 已取消: ${symbol}`)
        return
      }
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[stockAnalysisStore] loadStockAnalysis 失败: ${symbol}, ${message}`, {
        elapsedMs: Date.now() - t0,
      })
      set({
        loading: false,
        error: message,
      })
    }
  },

  refreshScore: async (symbol: string) => {
    const t0 = Date.now()
    logger.info(`[stockAnalysisStore] refreshScore 开始: ${symbol}`)
    set({ scoreLoading: true, error: null })

    try {
      logger.info(`[stockAnalysisStore] runV6Score 调用中...`, { symbol })
      const result = await runV6Score(symbol)
      logger.info(`[stockAnalysisStore] runV6Score 返回`, {
        symbol,
        success: result.success,
        hasData: !!result.data,
        elapsedMs: Date.now() - t0,
      })

      if (!result.success || !result.data) {
        const message = result.error ?? '评分计算失败'
        logger.error(`[stockAnalysisStore] refreshScore 失败: ${symbol}, ${message}`)
        set({ scoreLoading: false, error: message })
        return
      }

      logger.info(`[stockAnalysisStore] loadV6ScoreForAnalysis 调用中（获取最新评分）`, { symbol })
      const latest = await loadV6ScoreForAnalysis(symbol)
      logger.info(`[stockAnalysisStore] loadV6ScoreForAnalysis 返回`, {
        symbol,
        hasLatest: latest != null,
      })

      set({
        v6Score: latest ?? result.data,
        scoreLoading: false,
      })
      logger.info(`[stockAnalysisStore] refreshScore 完成: ${symbol}, 总耗时 ${Date.now() - t0}ms`)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[stockAnalysisStore] refreshScore 异常: ${symbol}, ${message}`, {
        elapsedMs: Date.now() - t0,
      })
      set({ scoreLoading: false, error: message })
    }
  },

  clear: () => {
    logger.info('[stockAnalysisStore] clear')
    set({ ...initialState })
  },

  setLoading: (loading: boolean) => {
    set({ loading })
  },

  setError: (error: string | null) => {
    set({ error })
  },
}))

// ============================================================
// DataBridge 订阅（用于跨模块数据同步）
// ============================================================

let _unsubscribeV6Scores: (() => void) | undefined
let _unsubscribeV6ScoresChanged: (() => void) | undefined

export function initStockAnalysisStoreSubscriptions(): () => void {
  destroyStockAnalysisStoreSubscriptions()
  logger.info('[stockAnalysisStore] 初始化 DataBridge + EventBus v6_scores 订阅')

  // 1. DataBridge 频道订阅(保留原有逻辑,修复 action 名)
  _unsubscribeV6Scores = dataBridge.subscribe(
    'v6_scores',
    (envelope) => {
      if (envelope.meta.action === ENVELOPE_ACTION.saveScores) {
        logger.info('[stockAnalysisStore] DataBridge event received: saveScores', {
          traceId: envelope.meta.traceId,
        })
      }
    },
  )

  // 2. 链路 7 修复:订阅 EventBus V6_SCORES_CHANGED,自动刷新 Store
  _unsubscribeV6ScoresChanged = eventBus.on(
    EVENT_NAMES.V6_SCORES_CHANGED,
    async (payload) => {
      const data = payload as { symbol?: string; score?: number } | undefined
      const symbol = data?.symbol
      if (!symbol) return

      const state = useStockAnalysisStore.getState()
      // 仅当当前选中的 symbol 匹配时才刷新
      if (state.selectedSymbol !== symbol) {
        logger.debug('[stockAnalysisStore] V6_SCORES_CHANGED symbol 不匹配,跳过', {
          eventSymbol: symbol,
          selectedSymbol: state.selectedSymbol,
        })
        return
      }

      logger.info('[stockAnalysisStore] V6_SCORES_CHANGED 触发 Store 刷新', {
        symbol,
        score: data.score?.toFixed(2),
      })

      try {
        const latest = await loadV6ScoreForAnalysis(symbol)
        useStockAnalysisStore.setState({ v6Score: latest ?? state.v6Score })
        logger.info('[stockAnalysisStore] V6 评分已自动刷新', { symbol })
      } catch (err) {
        logger.error('[stockAnalysisStore] V6 评分自动刷新失败', {
          symbol,
          error: err instanceof Error ? err.message : String(err),
        })
      }
    },
  )

  return () => destroyStockAnalysisStoreSubscriptions()
}

export function destroyStockAnalysisStoreSubscriptions(): void {
  if (_unsubscribeV6Scores) {
    _unsubscribeV6Scores()
    _unsubscribeV6Scores = undefined
  }
  if (_unsubscribeV6ScoresChanged) {
    _unsubscribeV6ScoresChanged()
    _unsubscribeV6ScoresChanged = undefined
  }
}

// 自动初始化订阅（与 systemMonitorStore / agentStore / widgetStore 保持一致）
initStockAnalysisStoreSubscriptions()

