  orders: [] as Order[],
  signals: [] as TradingSignal[],
  adviceMap: {} as Record<string, TradeAdvice>,
  portfolio: undefined as Portfolio | undefined,
  strategyResult: undefined as StrategyResult | undefined,
  portfolioLoading: false,
  processingSymbols: new Set<string>(),
  message: '',
  isRefreshing: false,
}

// ============================================================
// Store
// ============================================================

export const useTradingStore = create<TradingState>()((set, get) => ({
  ...initialState,

  // ----------------------------------------------------------
  // loadStocks —— 加载观察池并生成建议（委托）
  // ----------------------------------------------------------
  loadStocks: async () => {
    logger.info('[tradingStore] loadStocks 开始（委托给 watchlistStore + signalAdviceStore）')

    await useWatchlistStore.getState().loadStocks()
    const stocks = useWatchlistStore.getState().stocks

    if (stocks.length > 0) {
      await useSignalAdviceStore.getState().generateAdviceForStocks(stocks)
      // 同步子 Store 状态到 Facade
      set({
        stocks,
        adviceMap: useSignalAdviceStore.getState().adviceMap,
        message: '观察池与交易建议已更新',
      })
    } else {
      set({ stocks: [], message: '观察池为空' })
    }
  },

  // ----------------------------------------------------------
  // loadOrders —— 加载订单（委托）
  // ----------------------------------------------------------
  loadOrders: async () => {
    logger.info('[tradingStore] loadOrders 开始（委托给 orderStore）')
    await useOrderStore.getState().refresh()
    const orders = useOrderStore.getState().orders
    set({ orders })
    if (orders.length === 0) {
      set({ message: '订单列表为空' })
    }
  },

  // ----------------------------------------------------------
  // scanSignals —— 扫描信号（委托）
  // ----------------------------------------------------------
  scanSignals: async () => {
    logger.info('[tradingStore] scanSignals 开始（委托给 signalAdviceStore）')
    await useSignalAdviceStore.getState().scanSignals()
    const signals = useSignalAdviceStore.getState().signals
    set({ signals, message: `扫描完成，共 ${signals.length} 条信号` })
  },

  // ----------------------------------------------------------
  // loadPortfolio —— 构建核心组合（委托）
  // ----------------------------------------------------------
  loadPortfolio: async () => {
    logger.info('[tradingStore] loadPortfolio 开始（委托给 portfolioStore）')

    // 确保 stocks 和 orders 已加载
    if (useWatchlistStore.getState().stocks.length === 0) {
      await get().loadStocks()
    }
    if (useOrderStore.getState().orders.length === 0) {
      await get().loadOrders()
    }

    const currentStocks = useWatchlistStore.getState().stocks
    const currentOrders = useOrderStore.getState().orders

    set({ portfolioLoading: true })
    await usePortfolioStore.getState().buildPortfolio(currentStocks, currentOrders)

    const portfolio = usePortfolioStore.getState().portfolio
    set({
      portfolio: usePortfolioStore.getState().portfolio,
      strategyResult: usePortfolioStore.getState().strategyResult,
      portfolioLoading: false,
      message: portfolio && portfolio.holdings.length > 0
        ? `核心稀缺组合已构建，共 ${portfolio.holdings.length} 只标的`
        : '核心稀缺组合为空，无匹配标的或评分不足',
    })
  },

  // ----------------------------------------------------------
  // handleBuy —— 买入
  // ----------------------------------------------------------
  handleBuy: async (stock: Stock) => {
    const { processingSymbols } = get()
    if (processingSymbols.has(stock.symbol)) return

    set({ processingSymbols: new Set(processingSymbols).add(stock.symbol) })

    try {
      const adviceMap = useSignalAdviceStore.getState().adviceMap
      const advice = adviceMap[stock.symbol]
      const quantity = advice?.sizing?.action === 'buy' ? advice.sizing.targetShares : 100
      const result = await createBuyOrder(stock, quantity)

      if (result.success) {
        set({ message: `已买入 ${stock.symbol} ${quantity} 股` })
        await get().loadOrders()
        eventBus.emit(EVENT_NAMES.ORDERS_CHANGED, { action: 'buy', symbol: stock.symbol, quantity })
      } else {
        set({ message: result.error ?? '买入失败' })
      }
    } finally {
      const { processingSymbols: current } = get()
      const next = new Set(current)
      next.delete(stock.symbol)
      set({ processingSymbols: next })
    }
  },

  // ----------------------------------------------------------
  // handleSell —— 卖出
  // ----------------------------------------------------------
  handleSell: async (stock: Stock) => {
    const { processingSymbols } = get()
    if (processingSymbols.has(stock.symbol)) return

    set({ processingSymbols: new Set(processingSymbols).add(stock.symbol) })

    try {
      const adviceMap = useSignalAdviceStore.getState().adviceMap
      const advice = adviceMap[stock.symbol]
      const quantity =
        advice?.sizing?.action === 'sell'
          ? advice.sizing.targetShares
          : get().getHoldingShares(stock.symbol) || 100
      const result = await createSellOrder(stock, quantity)

      if (result.success) {
        set({ message: `已卖出 ${stock.symbol} ${quantity} 股` })
        await get().loadOrders()
        eventBus.emit(EVENT_NAMES.ORDERS_CHANGED, { action: 'sell', symbol: stock.symbol, quantity })
      } else {
        set({ message: result.error ?? '卖出失败' })
      }
    } finally {
      const { processingSymbols: current } = get()
      const next = new Set(current)
      next.delete(stock.symbol)
      set({ processingSymbols: next })
    }
  },

  // ----------------------------------------------------------
  // getHoldingShares —— 计算持仓股数
  // ----------------------------------------------------------
  getHoldingShares: (symbol: string): number => {
    const orders = useOrderStore.getState().orders
    return orders
      .filter((o) => o.symbol === symbol)
      .reduce((sum, o) => sum + (o.direction === 'buy' ? o.quantity : -o.quantity), 0)
  },

  // ----------------------------------------------------------
  // setMessage —— 设置消息
  // ----------------------------------------------------------
  setMessage: (msg: string) => {
    set({ message: msg })
  },

  // ----------------------------------------------------------
  // reset —— 重置
  // ----------------------------------------------------------
  reset: () => {
    logger.info('[tradingStore] reset')
    useWatchlistStore.getState().reset()
    useSignalAdviceStore.getState().reset()
    usePortfolioStore.getState().reset()
    set({ ...initialState, processingSymbols: new Set<string>() })
  },
}))

// ============================================================
// 子 Store 订阅同步 —— Facade 响应式更新
// ============================================================

let _unsubscribeFacade: (() => void) | null = null

/**
 * 初始化 Facade 的子 Store 订阅同步。
 * 当子 Store 状态变更时，自动同步到 Facade 状态，确保消费方响应式更新。
 *
 * @returns 清理函数
 */
export function initTradingStoreFacadeSync(): () => void {
  if (_unsubscribeFacade) {
    logger.warn('[tradingStore] Facade sync already initialized')
    return _unsubscribeFacade
  }

  const cleanupFns: Array<() => void> = []

  // 订阅 watchlistStore
  const unsubWatchlist = useWatchlistStore.subscribe((state) => {
    useTradingStore.setState({ stocks: state.stocks })
  })
  cleanupFns.push(unsubWatchlist)

  // 订阅 signalAdviceStore
  const unsubSignal = useSignalAdviceStore.subscribe((state) => {
    useTradingStore.setState({
      signals: state.signals,
      adviceMap: state.adviceMap,
    })
  })
  cleanupFns.push(unsubSignal)

  // 订阅 portfolioStore
  const unsubPortfolio = usePortfolioStore.subscribe((state) => {
    useTradingStore.setState({
      portfolio: state.portfolio,
      strategyResult: state.strategyResult,
      portfolioLoading: state.loading,
    })
  })
  cleanupFns.push(unsubPortfolio)

  // 订阅 orderStore
  const unsubOrder = useOrderStore.subscribe((state) => {
    useTradingStore.setState({ orders: state.orders })
  })
  cleanupFns.push(unsubOrder)

  _unsubscribeFacade = () => {
    cleanupFns.forEach((fn) => fn())
    _unsubscribeFacade = null
    logger.info('[tradingStore] Facade sync destroyed')
  }

  // 初始同步一次
  const wlState = useWatchlistStore.getState()
  const sigState = useSignalAdviceStore.getState()
  const pfState = usePortfolioStore.getState()
  const ordState = useOrderStore.getState()
  useTradingStore.setState({
    stocks: wlState.stocks,
    signals: sigState.signals,
    adviceMap: sigState.adviceMap,
    portfolio: pfState.portfolio,
    strategyResult: pfState.strategyResult,
    portfolioLoading: pfState.loading,
    orders: ordState.orders,
  })

  logger.info('[tradingStore] Facade sync initialized')
  return _unsubscribeFacade
}

/**
 * @module valuePitStore
 * @lifecycle @Global
 * @description 价值洼地策略评分状态管理。管理价值洼地五维评分列表，
 * 提供评分获取、单标的刷新、清空等操作，以及 topScores/buildCandidates/waitSignalList 等派生查询。
 *
 * @compliance
 * - 所有数据展示来自 valuePitAnalyzer 服务，禁止硬编码
 * - 核心分支包含 logger.info 打印
 * - 遵循现有 Zustand Store 风格
 */

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import type { ValuePitScore } from '@/data/types'
import { analyze, type ValuePitAnalyzerInput } from '@/services/scoring/valuePitAnalyzer'
import { detect, type RotationSignalInput, type RotationSignal } from '@/services/scoring/rotationSignalDetector'

const logger = getLogger()

// ============================================================
// 内部样本数据（后续由 dataLayer 替代）
// ============================================================

const DEFAULT_SAMPLES: ValuePitAnalyzerInput[] = [
  {
    symbol: '银行',
    sectorName: '银行',
    catalyst: { policyCatalyst: 4.0, cycleTurningPoint: 3.5, techBreakthrough: 2.0, orderSurge: 2.5 },
    valuationMargin: { pePercentile: 5, pbPercentile: 8, dividendYield: 4.5, peg: 0.6 },
    chipStructure: { northBoundChange: 2.5, fundPositionChange: 3.0, shareholderChange: -1.5 },
    rotationPosition: { sectorVolumePercentile: 15, capitalInflowStrength: 4.0, hasGoldenCross: true },
    liquidity: { avgDailyAmount: 80000, turnoverRate: 1.5, marketCap: 1500 },
  },
  {
    symbol: '钢铁',
    sectorName: '钢铁',
    catalyst: { policyCatalyst: 3.0, cycleTurningPoint: 3.0, techBreakthrough: 2.0, orderSurge: 2.0 },
    valuationMargin: { pePercentile: 15, pbPercentile: 20, dividendYield: 3.0, peg: 0.8 },
    chipStructure: { northBoundChange: 1.0, fundPositionChange: 1.5, shareholderChange: -0.5 },
    rotationPosition: { sectorVolumePercentile: 40, capitalInflowStrength: 3.0, hasGoldenCross: false },
    liquidity: { avgDailyAmount: 30000, turnoverRate: 2.5, marketCap: 500 },
  },
  {
    symbol: '煤炭',
    sectorName: '煤炭',
    catalyst: { policyCatalyst: 2.5, cycleTurningPoint: 2.0, techBreakthrough: 1.5, orderSurge: 1.5 },
    valuationMargin: { pePercentile: 10, pbPercentile: 12, dividendYield: 5.0, peg: 0.5 },
    chipStructure: { northBoundChange: -0.5, fundPositionChange: 0.5, shareholderChange: 2.0 },
    rotationPosition: { sectorVolumePercentile: 55, capitalInflowStrength: 2.0, hasGoldenCross: false },
    liquidity: { avgDailyAmount: 15000, turnoverRate: 1.0, marketCap: 300 },
  },
]

// ============================================================
// 轮动信号检测样本数据（与 DEFAULT_SAMPLES 对应）
// ============================================================

const DEFAULT_ROTATION_INPUTS: RotationSignalInput[] = [
  {
    sectorId: '银行',
    volume: { history: [...Array(50).fill(60000), 100000, 110000, 120000, 115000, 105000] },
    capitalFlow: { dailyNetFlow: [10, 20, 15, 30, 25] },
    goldenCross: { closes: [...Array(20).fill(105), 100, 100, 100, 100, 130] },
  },
  {
    sectorId: '钢铁',
    volume: { history: [...Array(50).fill(30000), 35000, 32000, 31000, 33000, 34000] },
    capitalFlow: { dailyNetFlow: [5, 3, -2, 8, 2] },
    goldenCross: { closes: [...Array(25).fill(100)] },
  },
  {
    sectorId: '煤炭',
    volume: { history: [...Array(40).fill(15000), ...Array(10).fill(20000), 16000, 16000, 16000, 16000, 16000] },
    capitalFlow: { dailyNetFlow: [-3, -5, -2, 1, -1] },
    goldenCross: { closes: Array(25).fill(100).map((v, i) => v - i * 0.5) },
  },
]

// ============================================================
// 组合结果类型
// ============================================================

export interface ValuePitSectorResult {
  score: ValuePitScore
  rotation: RotationSignal
}

// ============================================================
// Store 接口
// ============================================================

interface ValuePitState {
  /** 评分列表 */
  scores: ValuePitScore[]
  /** 轮动信号列表 */
  rotationSignals: RotationSignal[]
  /** 组合结果（评分 + 轮动信号） */
  combinedResults: ValuePitSectorResult[]
  /** 加载状态 */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 最后更新时间戳 */
  lastUpdated: number

  // Actions
  /** 运行组合分析（价值洼地评分 + 轮动信号检测） */
  runAnalysis: () => void
  fetchScores: (inputs?: ValuePitAnalyzerInput[]) => void
  refreshScore: (symbol: string, inputs?: ValuePitAnalyzerInput[]) => void
  clearScores: () => void
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  scores: [] as ValuePitScore[],
  rotationSignals: [] as RotationSignal[],
  combinedResults: [] as ValuePitSectorResult[],
  loading: false,
  error: null as string | null,
  lastUpdated: 0,
}

// ============================================================
// Store
// ============================================================

export const useValuePitStore = create<ValuePitState>((set) => ({
  ...initialState,

  runAnalysis: () => {
    logger.info('[valuePitStore] runAnalysis 开始')
    set({ loading: true, error: null })

    try {
      const combinedResults: ValuePitSectorResult[] = DEFAULT_SAMPLES.map((input, index) => {
        const score = analyze(input)
        const rotationInput = DEFAULT_ROTATION_INPUTS[index]!
        const rotation = detect(rotationInput)
        logger.info(
          `[valuePitStore] ${input.symbol} 评分: score=${score.score.toFixed(2)} ` +
          `action=${score.action} rotation=${rotation.triggered ? rotation.strength : '无'}`,
        )
        return { score, rotation }
      })

      combinedResults.sort((a, b) => b.score.score - a.score.score)
      set({
        scores: combinedResults.map((r) => r.score),
        rotationSignals: combinedResults.map((r) => r.rotation),
        combinedResults,
        loading: false,
        lastUpdated: Date.now(),
      })
      logger.info(`[valuePitStore] runAnalysis 完成: ${combinedResults.length} 个板块`)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[valuePitStore] runAnalysis 失败: ${message}`)
      set({ error: message, loading: false })
    }
  },

  fetchScores: (inputs) => {
    logger.info('[valuePitStore] fetchScores 开始')
    set({ loading: true, error: null })

    try {
      const sourceInputs = inputs ?? DEFAULT_SAMPLES
      const results = sourceInputs.map((input) => {
        const score = analyze(input)
        logger.info(
          `[valuePitStore] ${input.symbol} 评分: score=${score.score.toFixed(2)} action=${score.action}`,
        )
        return score
      })

      results.sort((a, b) => b.score - a.score)
      set({
        scores: results,
        loading: false,
        lastUpdated: Date.now(),
      })
      logger.info(`[valuePitStore] fetchScores 完成: ${results.length} 个板块`)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[valuePitStore] fetchScores 失败: ${message}`)
      set({ error: message, loading: false })
    }
  },

  refreshScore: (symbol, inputs) => {
    logger.info(`[valuePitStore] refreshScore: ${symbol}`)
    const sourceInputs = inputs ?? DEFAULT_SAMPLES
    const target = sourceInputs.find((i) => i.symbol === symbol)

    if (!target) {
      logger.warn(`[valuePitStore] refreshScore 未找到标的: ${symbol}`)
      return
    }

    try {
      const newScore = analyze(target)
      set((state) => {
        const scores = state.scores.map((s) =>
          s.symbol === symbol ? newScore : s,
        )
        scores.sort((a, b) => b.score - a.score)
        return { scores, lastUpdated: Date.now() }
      })
      logger.info(`[valuePitStore] refreshScore 完成: ${symbol} score=${newScore.score.toFixed(2)}`)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[valuePitStore] refreshScore 失败: ${message}`)
      set({ error: message })
    }
  },

  clearScores: () => {
    logger.info('[valuePitStore] clearScores')
    set({
      scores: [],
      rotationSignals: [],
      combinedResults: [],
      loading: false,
      error: null,
      lastUpdated: 0,
    })
  },
}))

// ============================================================
// 派生查询（Getters）
// ============================================================

/** 获取 Top N 评分 */
export function topScores(limit: number = 5): ValuePitScore[] {
  const { scores } = useValuePitStore.getState()
  return scores.slice(0, limit)
}

/** 获取建仓候选列表 */
export function buildCandidates(): ValuePitScore[] {
  const { scores } = useValuePitStore.getState()
  return scores.filter((s) => s.action === 'immediate')
}

/** 获取等待信号列表 */
export function waitSignalList(): ValuePitScore[] {
  const { scores } = useValuePitStore.getState()
  return scores.filter((s) => s.action === 'wait')
}
